(window.GIM_TP=window.GIM_TP||{})["Sanhedrin.1"]={"from":206,"a":[[["דקאתי מיהודה מואב סיר רחצי זה גחזי שלקה על עסקי רחיצה על אדום אשליך נעלי זה דואג האדומי עלי פלשת התרועעי אמרו מלאכי השרת לפני הקב\"ה רבש\"ע אם יבא דוד שהרג את הפלשתי והוריש את בניך גת מה אתה עושה לו אמר להן עלי לעשותן ריעים זה לזה","(ירמיהו ח, ה) מדוע שובבה העם הזה ירושלים משובה נצחת וגו' אמר רב תשובה נצחת השיבה כנסת ישראל לנביא אמר להן נביא לישראל חזרו בתשובה אבותיכם שחטאו היכן הם אמרו להן ונביאיכם שלא חטאו היכן הם שנאמר (זכריה א, ה) אבותיכם איה הם והנביאים הלעולם יחיו אמר להן (אבותיכם) חזרו והודו שנאמר (זכריה א, ו) אך דברי וחוקי אשר צויתי את עבדי הנביאים וגו'","שמואל אמר באו עשרה בני אדם וישבו לפניו אמר להן חזרו בתשובה אמרו לו עבד שמכרו רבו ואשה שגרשה בעלה כלום יש לזה על זה כלום אמר לו הקב\"ה לנביא לך אמור להן (ישעיהו נ, א) איזה ספר כריתות אמכם אשר שלחתיה או מי מנושי אשר מכרתי אתכם לו הן בעונותיכם נמכרתם ובפשעכם שלחה אמכם","והיינו דאמר ריש לקיש מאי דכתיב דוד עבדי (ירמיהו מג, י) נבוכדנצר עבדי גלוי וידוע לפני מי שאמר והיה העולם שעתידין ישראל לומר כך לפיכך הקדים הקב\"ה וקראו עבדו עבד שקנה נכסים עבד למי נכסים למי","(יחזקאל כ, לב) והעולה על רוחכם היה לא תהיה אשר אתם אומרים נהיה כגוים כמשפחות הארצות לשרת עץ ואבן חי אני נאם ה' אלהים אם לא ביד חזקה ובזרוע נטויה ובחימה שפוכה אמלוך עליכם אמר רב נחמן כל כי האי ריתחא לירתח רחמנא עלן ולפרוקינן","(ישעיהו כח, כו) ויסרו למשפט אלהיו יורנו אמר רבה בר בר חנה אמר להן נביא לישראל חזרו בתשובה אמרו לו אין אנו יכולין יצר הרע שולט בנו אמר להם יסרו יצריכם אמרו לו אלהיו יורנו:","ארבעה הדיוטות בלעם ודואג ואחיתופל וגחזי: בלעם בלא עם דבר אחר בלעם שבלה עם בן בעור שבא על בעיר","תנא הוא בעור הוא כושן רשעתים הוא לבן הארמי בעור שבא על בעיר כושן רשעתים דעבד שתי רשעיות בישראל אחת בימי יעקב ואחת בימי שפוט השופטים ומה שמו לבן הארמי שמו","כתיב (במדבר כב, ה) בן בעור וכתיב (במדבר כד, ג) בנו בעור אמר רבי יוחנן אביו בנו הוא לו בנביאות","בלעם הוא דלא אתי לעלמא דאתי הא אחריני אתו מתניתין מני","רבי יהושע היא דתניא ר\"א אומר (תהלים ט, יח) ישובו רשעים לשאולה כל גוים שכחי אלהים ישובו רשעים לשאולה אלו פושעי ישראל כל גוים שכחי אלהים אלו פושעי עובדי כוכבים דברי ר\"א אמר לו ר' יהושע וכי נאמר בכל גוים והלא לא נאמר אלא כל גוים שכחי אלהים אלא ישובו רשעים לשאולה מאן נינהו כל גוים שכחי אלהים","ואף אותו רשע נתן סימן בעצמו אמר (במדבר כג, י) תמות נפשי מות ישרים אם תמות נפשי מות ישרים תהא אחריתי כמוהו ואם לאו הנני הולך לעמי","וילכו זקני מואב וזקני מדין תנא מדין ומואב לא היה להם שלום מעולם משל לשני כלבים שהיו בעדר והיו צהובין זה לזה בא זאב על האחד אמר האחד אם איני עוזרו היום הורג אותו ולמחר בא עלי הלכו שניהם והרגו הזאב אמר רב פפא היינו דאמרי אינשי כרכושתא ושונרא עבדו הלולא מתרבא דביש גדא","(במדבר כב, ח) וישבו שרי מואב עם בלעם ושרי מדין להיכן אזול כיון דאמר להו (במדבר כב, ח) לינו פה הלילה והשבותי אתכם דבר אמרו כלום יש אב ששונא את בנו","אמר רב נחמן חוצפא אפילו כלפי שמיא מהני מעיקרא כתיב לא תלך עמהם ולבסוף כתיב קום לך אתם אמר רב ששת חוצפא מלכותא בלא תאגא היא דכתיב (שמואל ב ג, לט) ואנכי היום רך ומשוח מלך והאנשים האלה בני צרויה קשים ממני וגו'","א\"ר יוחנן בלעם חיגר ברגלו אחת היה שנאמר (במדבר כג, ג) וילך שפי שמשון בשתי רגליו שנאמר (בראשית מט, יז) שפיפון עלי אורח הנושך עקבי סוס בלעם סומא באחת מעיניו היה שנאמר (במדבר כד, ג) שתום העין","קוסם באמתו היה כתיב הכא נופל וגלוי עינים וכתיב התם (אסתר ז, ח) והנה המן נופל על המטה וגו' איתמר מר זוטרא אמר קוסם באמתו היה מר בריה דרבינא אמר שבא על אתונו מ\"ד קוסם באמתו היה כדאמרן ומ\"ד בא על אתונו היה כתיב הכא (במדבר כד, ט) כרע שכב וכתיב התם (שופטים ה, כז) בין רגליה"],[[0,"דקא אתי מיהודה","דקאמר לו דוד ואתה אנוש כערכי אלופי ומיודעי שהיה קורא לאחיתופל מיודעי קרובי שהיה משבט יהודה כדוד:"],[0,"מואב סיר רחצי","דוד דקא אתי ממואב:"],[0,"סיר רחצי","גחזי שסר ונצטרע על עסקי רחיצה:"],[0,"על אדום אשליך נעלי","אנעיל אותם בגן עדן:"],[0,"אם יבא דוד שהרג את הפלשתי","ויצעק לפניך על שאתה נותן חלק לדואג ואחיתופל לעוה\"ב מה אתה עושה להפיס דעתו שהם היו שונאין אותו:"],[0,"אמר להם","עלי לפייסן ולעשותן ריעים ואהובים זה לזה והיינו התרועעי לשון ריעות:"],[2,"ושמואל אמר","מאי תשובה נצחת כה\"ג [באו] עשרה בני אדם וכו':"],[2,"עבד שמכרו רבו","ומאחר שמכרנו הקב\"ה לנבוכדנצר וגרשנו מעליו יש לו עלינו כלום:"],[3,"מאי דכתיב ודוד עבדי נבוכדנצר עבדי","שקראו לאותו רשע עבד כמו שקראו לדוד דכתיב בסוף ירמיה (מב) הנני שולח ולקחתי את נבוכדנצר עבדי לא מפני שדומה זה לזה אלא גלוי וידוע לפני מי שאמר והיה העולם שעתידין ישראל לומר כבר מכרנו הקב\"ה לנבוכדנצר לפיכך הקדים הקב\"ה וקרא עבדי לנבוכדנצר כדי להחזיר להן תשובה:"],[3,"עבד למי נכסים למי","כלומר נבוכדנצר עבדי הוא וכל מה שקנה לי הוא ועדיין לא יצאתם מרשותי:"],[4,"והעולה על רוחכם היה לא תהיה","כל מה שאתם סבורים לא יהיה:"],[4,"כל כי האי ריתחא","מי יתן ויבא לנו זה הכעס בחימה שפוכה אמלוך עליכם שיגאלנו בעל כרחנו וימלוך עלינו:"],[5,"א\"ר אבא בר כהנא","היינו תשובה נצחת דאמרו ליה אלהים יורנו שאין אנו יכולין ליסר אותו:"],[6,"בלא עם","שאין לו חלק עם עם:"],[6,"שבלה עם","שבלבל ישראל בעצתו שהשיאו לבלק כדבעינן למימר לקמן והפיל מהם כ\"ד אלפים:"],[6,"בעור שבא על בעיר","שבא על אתונו כמו בהמה דמתרגמינן בעיר:"],[7,"תנא הוא בעור","אביו של בלעם הוא כושן רשעתים הוא לבן הארמי:"],[7,"אחת בימי יעקב","שרדף אחריו ובקש לעקור הכל:"],[7,"ואחת בימי שופטים","לאחר מיתת יהושע דכתיב (שופטים ג׳:ח׳) ויחר אף ה' בישראל ויתנם ביד כושן רשעתים:"],[8,"בנו בעור","משמע בעור בנו של בלעם היה:"],[8,"בנו הוא","לבלעם בנביאות שבלעם גדול מאביו היה בנביאות:"],[9,"הא שאר נכרים אתו","כלומר מדקא חשיב תנא דמתניתין דבלעם שהיה נכרי בהדי הדיוטות וקאמר דאין לו חלק מכלל דשאר נכרים יש להם חלק:"],[9,"מתניתין מני וכו'","א״ל ר' יהושע אלו נאמר ישובו רשעים לשאולה בכל הגוים משמע כדקאמרת השתא דכתיב כל גוים שכחי אלהים לא משמע אלא אותן השוכחים אלוה כגון בלעם [ושכמותו] אבל אחריני אתו כדאמרינן בריש פרקין (סנהדרין דף צא:) ורעו זרים צאנכם ובני נכר אכריכם לעולם הבא:"],[10,"מאי נינהו כל גוים שכחי אלהים","דמשום הכי בורר הקב\"ה הרשעים שבהם ונותן אותם בגיהנם ואין להם חלק לעתיד אבל השאר יש להם חלק:"],[11,"ואף אותו רשע נתן סימן בעצמו","שאין לו חלק לעתיד:"],[11,"תמות נפשי מות ישרים","אם ימות מיתת עצמו תהא אחריתי כמוהו דודאי יש לו חלק עמהם:"],[11,"ואם לאו","דלא ימות אלא יהרג הנני הולך לעמי לגיהנם:"],[12,"לא היה להם שלום","דכתיב המכה את מדין בשדה מואב:"],[12,"צהובין","כעוסין כאדם שכועס פניו צהובין:"],[12,"כרכושתא","חולדה:"],[12,"כרכושתא ושונרא","אין להם שלום מעולם:"],[12,"ביש גדא","מזל רע:"],[13,"כלום יש אב ששונא את בנו","שהוא סבור שיאמר לו הקב\"ה קלל את בני דקאמר בלעם לינו פה [הלילה]:"],[14,"חוצפא אפילו כלפי שמיא מהני","דאהני ליה מה שהחציף פניו לומר לשלוחי בלק לינו פה שאמר לו הקב\"ה בתחילה לא תלך והדר אמר לך:"],[14,"מלכותא בלא תגא","כלומר שררה גדולה ואינו חסר אלא כתר מלכות:"],[14,"אנכי היום רך ומשוח מלך והאנשים האלה קשים ממני","כלומר איני גדול מהם אלא משיחת מלכות:"],[15,"שפי","כמו (חולין דף נד:) בוקא דאטמא דשף מדוכתיה:"],[15,"שפיפון","משמעו שתים:"],[15,"שתום העין","שתום פתוח כמו שתומו ניכר כלומר עינו אחת פתוחה מכלל דהאחרת סתומה והכי נמי מתרגמינן דשפיר חזי אית דמפרשי שתום כמו סתום ולאו מילתא היא:"],[16,"קוסם באמתו","כגון מעלה בזכורו:"]],[]],[["כרע נפל שכב וגו'","(במדבר כד, טז) ויודע דעת עליון השתא דעת בהמתו לא הוה ידע דעת עליון הוה ידע מאי דעת בהמתו דאמרי ליה מאי טעמא לא רכבת סוסיא אמר להו שדאי להו ברטיבא","אמרה ליה הלא אנכי אתונך לטעינא בעלמא אשר רכבת עלי אקראי בעלמא מעודך עד היום הזה","ולא עוד אלא שאני עושה [לך] מעשה אישות בלילה כתיב הכא (במדבר כב, ל) ההסכן הסכנתי וכתיב התם (מלכים א א, ב) ותהי לו סוכנת","אלא מאי ויודע דעת עליון שהיה יודע לכוון אותה שעה שהקב\"ה כועס בה","והיינו דקאמר להו נביא לישראל (מיכה ו, ה) עמי זכר נא מה יעץ בלק מלך מואב ומה ענה אותו בלעם בן בעור מן השטים ועד הגלגל למען דעת צדקות ה' מאי למען דעת צדקות ה' אמר להן הקב\"ה לישראל דעו נא כמה צדקות עשיתי עמכם שלא כעסתי כל אותן הימים בימי בלעם הרשע שאילמלא כעסתי כל אותן הימים לא נשתייר משונאיהן של ישראל שריד ופליט","היינו דקאמר ליה בלעם לבלק מה אקב לא קבה אל (וגו' אותן היום [הימים] לא זעם ה') אל זועם בכל יום וכמה זעמו רגע שנאמר (תהלים ל, ו) כי רגע באפו חיים ברצונו וגו'","איבעית אימא (ישעיהו כו, כ) לך עמי בא בחדריך וסגור דלתיך בעדך חבי כמעט רגע עד יעבור זעם אימת רתח בתלת שעי קמייתא כי חוורא כרבלתא דתרנגולא כל שעתא ושעתא נמי חוורא כל שעתא ושעתא אית ביה סוריקי סומקי ההיא שעתא לית ביה סוריקי סומקי","ההוא מינא דהוה בשיבבותיה דרבי יהושע בן לוי דהוה קא מצער ליה יומא חד נקט תרנגולתא ואסר ליה בכרעיה ואותיב אמר כי מטא ההוא שעתא אילטייה כי מטא ההוא שעתא נמנם אמר שמע מינה לאו אורח ארעא דכתיב (משלי יז, כו) גם ענוש לצדיק לא טוב אפילו במיני לא איבעי ליה למימר הכי","תנא משמיה דרבי מאיר בשעה שהחמה זורחת והמלכים מניחין כתריהן על ראשיהן ומשתחוים לחמה מיד כועס","(במדבר כב, כא) ויקם בלעם בבקר ויחבוש את אתונו תנא משום רבי שמעון בן אלעזר אהבה מבטלת שורה של גדולה מאברהם דכתיב (בראשית כא, יד) וישכם אברהם בבקר שנאה מבטלת שורה של גדולה מבלעם שנאמר ויקם בלעם בבקר ויחבוש את אתונו","אמר רב יהודה אמר רב לעולם יעסוק אדם בתורה ובמצוה אפילו שלא לשמה שמתוך שלא לשמה בא לשמה שבשכר ארבעים ושתים קרבנות שהקריב בלק זכה ויצאה ממנו רות א\"ר יוסי בר הונא רות בתו של עגלון בן בנו של בלק מלך מואב היתה","א\"ל רבא לרבה בר מרי כתיב (מלכים א א, מז) ייטב אלהים את שם שלמה משמך ויגדל [את] כסאו מכסאך אורח ארעא למימרא ליה למלכא הכי א\"ל מעין קאמרה ליה","דאי לא תימא הכי (שופטים ה, כד) תבורך מנשים יעל אשת חבר הקיני מנשים באהל תבורך נשים באהל מאן נינהו שרה רבקה רחל ולאה אורח ארעא למימר הכי אלא מעין קאמר הכא נמי מעין קאמר","ופליגא דרב יוסי בר חוני דאמר רב יוסי בר חוני בכל אדם מתקנא חוץ מבנו ותלמידו בנו משלמה ותלמידו איבעית אימא (מלכים ב ב, ט) ויהי נא פי שנים ברוחך אלי ואיבעית אימא (במדבר כז, כג) ויסמוך את ידיו עליו ויצוהו","(במדבר כג, ה) וישם דבר בפי בלעם ר\"א אומר מלאך ר' יונתן אמר חכה","א\"ר יוחנן מברכתו של אותו רשע אתה למד מה היה בלבו ביקש לומר שלא יהו להם בתי כנסיות ובתי מדרשות (במדבר כד, ה) מה טובו אהליך יעקב לא תשרה שכינה עליהם ומשכנותיך ישראל לא תהא מלכותן נמשכת כנחלים נטיו לא יהא להם זיתים וכרמים כגנות עלי נהר לא יהא ריחן נודף כאהלים נטע ה'","לא יהיו להם מלכים בעלי קומה כארזים עלי מים לא יהיה להם מלך בן מלך יזל מים מדליו לא תהא מלכותן שולטת באומות וזרעו במים רבים לא תהא עזה מלכותן וירם מאגג מלכו לא תהא אימת מלכותן ותנשא מלכותו","אמר רבי אבא בר כהנא כולם חזרו לקללה חוץ מבתי כנסיות ומבתי מדרשות שנאמר (דברים כג, ו) ויהפוך ה' אלהיך לך את הקללה לברכה כי אהבך ה' אלהיך קללה ולא קללות","א\"ר שמואל בר נחמני א\"ר יונתן מאי דכתיב (משלי כז, ו) נאמנים פצעי אוהב ונעתרות נשיקות שונא טובה קללה שקילל אחיה השילוני את ישראל יותר מברכה שברכם בלעם הרשע אחיה השילוני קילל את ישראל בקנה שנאמר (מלכים א יד, טו) והכה ה' את ישראל כאשר ינוד הקנה במים וגו' מה קנה זה עומד במקום מים וגיזעו"],[[0,"כרע נפל","מה כריעה דהתם דאית ביה נפילה בעילה היא אף כריעה דהכא דכתיב נופל בעילה היא שבא על בהמתו:"],[1,"דעת בהמתו לא הוה ידע","מאי בעיא לאהדורי כדמפרש דאמרי ליה שרי בלק מאי טעמא לא רכבת אסוסיא:"],[1,"ברטיבא","באחו לרעות עשבים לחים:"],[2,"אמר להו לטעינא בעלמא","לישא משאות ולא לרכוב:"],[2,"","אמרה ליה אשר רכבת עלי:"],[2,"אקראי בעלמא","כשאין לי סוס מזומן:"],[2,"","אמרה לו מעודך:"],[3,"מעשה אישות","שאתה בועלי:"],[3,"סוכנת","מחממת:"],[5,"מן השטים ועד הגלגל","משחטאו בשטים ועד שנכנסו לארץ וחטאו בגלגל עשיתי עמהם צדקות הרבה:"],[5,"כל אותן הימים","שהיה בלעם מצפה לקללכם בשעה שהקב\"ה כועס בה כל הקללות מתקיימות:"],[6,"ה\"ג לא זעם ה'","אותן הימים לא זעם ה':"],[6,"אל זועם בכל יום","קרא הוא:"],[6,"כמה זעמו רגע","כדמפיק ליה מקרא כי רגע באפו חיים ברצונו:"],[7,"בתלת שעי קמייתא","של יום זמן קימה שכל שלש שעות זמן קימה לעמוד ממטתו וכועס הקב\"ה בשעה שרואה המלכים שמשתחוים לחמה בשעה שמניחין כתריהם בראשם כדלקמן:"],[7,"כרבלתא","קירשת\"א בלע\"ז:"],[7,"כל שעתא נמי חיורא","רוב שעות מתלבנות ומכספת שאינה כל שעה בחוזק אדמימות:"],[7,"סורייקי סומקי","אפי' כשמכספת יש בה שורות שורות אדומות מאד כרגילותם אבל אותה שעה כולה מכספת:"],[8,"גם ענוש לצדיק לא טוב","אין נכון לצדיק שיהא מעניש ולא הוה ליה איניש נענש בשבילו:"],[10,"אהבה","שאהב הקב\"ה את אברהם ביטלה שורה של גדולה שחבש הוא בעצמו:"],[10,"ושנאה","ששנא בלעם הרשע את ישראל ביטלה שורה של גדולה שחבש הוא בעצמו:"],[11,"מ\"ב קרבנות","בין פרים לאילים ז' פרים וז' אילים ג' פעמים הרי מ\"ב בין פרים ואילים:"],[12,"אורח ארעא למימר הכי","וכי דרך ארץ כן שיאמרו וייטב אלהים שם שלמה משמך והא חלשא דעתיה דאמרי ליה שיהא גדול מאביו:"],[12,"מעין שמך","קאמר ליה ומעין כסאך ולא גדול ממש:"],[13,"נשים באהל","שרה רבקה רחל ולאה שרה ורבקה דכתיב ויביאה יצחק האהלה שרה אמו וגו' רחל ולאה דכתיב (בראפית לא) ויצא מאהל לאה ויבא באהל רחל:"],[13,"אורח ארעא","שאמרה דבורה ליעל [שתהא] ברוכה משרה ורבקה אלא מעין ברכת שרה קאמרה:"],[14,"ופליגא","האי דמשנינן שם שלמה משמך מעין פליגא דר' יוסי בר חוני:"],[14,"בנו מניין","שאינו מקנא בו:"],[14,"משלמה","דקאמרי ליה לדוד ייטב אלהים שם שלמה משמך:"],[14,"ותלמידו","איבעית אימא דקאמר ליה לאליהו ויהי נא פי שנים ברוחך אלי ונתן לו אליהו ולא נתקנא בו:"],[14,"ויסמוך את ידיו עליו ויצוהו","אע\"ג דהקב\"ה לא א\"ל אלא וסמכת את ידך עליו חדא אזיל איהו וסמך תרתי:"],[15,"מלאך","שמסרו הקדוש ברוך הוא למלאך שלא יניחנו לקלל:"],[15,"חכה","נתן בפי בלעם שלא היה מניחו לקלל והיינו וישם:"],[16,"מברכותיו אתה למד מה היה בלבו","דכתיב ויהפוך ה' אלהיך לך את הקללה לברכה הוא היה רוצה לקללם בכך שלא יהיו בתי כנסיות ולא נתן רשות ואמר מה טובו אוהליך:"],[16,"ריחו נודף","ממצות:"],[17,"וירם מאגג מלכו","מתרגמינן ותתקף מאגג שתהא מלכותו עזה:"],[18,"וכולם","כל הברכות של בלעם חזרו לקללה כמו שהיה כוונתו מתחילה:"],[18,"חוץ מבתי כנסיות ובתי מדרשות","שלא יפסקו מישראל לעולם:"],[18,"הקללה לברכה","אחת מן הקללות הפך לברכה שלא חזרה לעולם ולא כל הקללות לברכות שחזרו:"],[19,"נעתרות","נהפכות כמו עתר שמהפך התבואה כלומר נאמנים פצעי אוהב ונהפכות מנאמנות נשיקות שונא:"]],[]],[["מחליף ושרשיו מרובין ואפילו כל רוחות שבעולם באות ונושבות בו אין מזיזות אותו ממקומו אלא הוא הולך ובא עמהן כיון שדוממו הרוחות עמד קנה במקומו","אבל בלעם הרשע ברכן בארז מה ארז זה אינו עומד במקום מים ושרשיו מועטין ואין גזעו מחליף אפילו כל הרוחות שבעולם באות ונושבות בו אין מזיזות אותו ממקומו כיון שנשבה בו רוח דרומית מיד עוקרתו והופכתו על פניו ולא עוד אלא שזכה קנה ליטול ממנו קולמוס לכתוב ממנו ס\"ת נביאים וכתובים","(במדבר כד, כא) וירא את הקיני וישא משלו אמר לו בלעם ליתרו קיני לא היית עמנו באותה עצה מי הושיבך אצל איתני עולם","והיינו דא\"ר חייא בר אבא א\"ר סימאי שלשה היו באותה עצה אלו הן בלעם איוב ויתרו בלעם שיעץ נהרג איוב ששתק נידון ביסורין ויתרו שברח זכו בני בניו לישב בלשכת הגזית שנאמר (דברי הימים א ב, נה) ומשפחות סופרים יושבי יעבץ תרעתים שמעתים סוכתים המה הקינים הבאים מחמת אבי בית רכב וכתיב (שופטים א, טז) ובני קיני חותן משה עלו מעיר התמרים","(במדבר כד, כג) וישא משלו ויאמר אוי מי יחיה משמו אל (אמר רשב\"ל אוי מי שמחיה עצמו בשם אל) א\"ר יוחנן אוי לה לאומה שתמצא בשעה שהקב\"ה עושה פדיון לבניו מי מטיל כסותו בין לביא ללביאה בשעה שנזקקין זה עם זה","(במדבר כד, כד) וצים מיד כתים אמר רב ליבון אספיר (במדבר כד, כד) וענו אשור וענו עבר עד אשור קטלי מיקטל מכאן ואילך משעבדי שיעבודי","(במדבר כד, יד) הנני הולך לעמי לכה איעצך אשר יעשה העם הזה לעמך עמך לעם הזה מיבעי ליה א\"ר אבא בר כהנא כאדם שמקלל את עצמו ותולה קללתו באחרים","אמר להם אלהיהם של אלו שונא זימה הוא והם מתאוים לכלי פשתן בוא ואשיאך עצה עשה להן קלעים והושיב בהן זונות זקינה מבחוץ וילדה מבפנים וימכרו להן כלי פשתן","עשה להן קלעים מהר שלג עד בית הישימות והושיב בהן זונות זקינה מבחוץ וילדה מבפנים ובשעה שישראל אוכלין ושותין ושמחין ויוצאין לטייל בשוק אומרת לו הזקינה אי אתה מבקש כלי פשתן זקינה אומרת לו בשוה וילדה אומרת לו בפחות שתים ושלש פעמים","ואח\"כ אומרת לו הרי את כבן בית שב ברור לעצמך וצרצורי של יין עמוני מונח אצלה ועדיין לא נאסר (יין של עמוני ולא) יין של נכרים אמרה לו רצונך שתשתה כוס של יין כיון ששתה בער בו","אמר לה השמיעי לי הוציאה יראתה מתוך חיקה אמרה לו עבוד לזה אמר לה הלא יהודי אני אמרה לו ומה איכפת לך כלום מבקשים ממך אלא פיעור [והוא אינו יודע שעבודתה בכך] ולא עוד אלא שאיני מנחתך עד שתכפור בתורת משה רבך שנא' (הושע ט, י) המה באו בעל פעור וינזרו לבשת ויהיו שקוצים באהבם","(במדבר כה, א) וישב ישראל בשטים ר\"א אומר שטים שמה רבי יהושע אומר שנתעסקו בדברי שטות","ותקראן לעם לזבחי אלהיהן רבי אלעזר אומר ערומות פגעו בהן רבי יהושע אומר שנעשו כולן בעלי קריין","מאי לשון רפידים רבי אליעזר אומר רפידים שמה רבי יהושע אומר שריפו עצמן מדברי תורה שנאמר (ירמיהו מז, ג) לא הפנו אבות אל בנים מרפיון ידים","אמר רבי יוחנן כל מקום שנאמר וישב אינו אלא לשון צער שנא' (במדבר כה, א) וישב ישראל בשטים ויחל העם לזנות אל בנות מואב (בראשית לז, א) וישב יעקב בארץ מגורי אביו בארץ כנען ויבא יוסף את דבתם רעה אל אביהם ונאמר (בראשית מז, כז) וישב ישראל בארץ גשן ויקרבו ימי ישראל למות (מלכים א ה, ה) וישב יהודה וישראל לבטח איש תחת גפנו ותחת תאנתו (מלכים א יא, יד) ויקם ה' שטן לשלמה את הדד האדומי מזרע המלך הוא באדום","(במדבר לא, ח) ואת מלכי מדין הרגו על חלליהם וגו' את בלעם בן בעור הרגו בחרב בלעם מאי בעי התם א\"ר יוחנן שהלך ליטול שכר עשרים וארבעה אלף [שהפיל מישראל] אמר מר זוטרא בר טוביה אמר רב היינו דאמרי אינשי גמלא אזלא למיבעי קרני אודני דהוו ליה גזיזן מיניה","(יהושע יג, כב) ואת בלעם בן בעור הקוסם קוסם נביא הוא א\"ר יוחנן בתחלה נביא ולבסוף קוסם אמר רב פפא היינו דאמרי אינשי מסגני ושילטי הואי אייזן לגברי נגרי"],[[0,"מחליף","לאחר שנקצץ:"],[1,"אינו עומד במקום מים","והאי דכתיב כארזים עלי מים שכינה היא דאמרה איהו אמר כארזים כלומר שאין עומדין במקום מים שכינה אמרה עלי מים וכן כולהו מפרש באגדה בכה\"ג כנחלים נטיו הוא אמר כנחלים פוסקין לפעמים יצאה בת קול [אמרה] נטיו הוא אמר כגנות אמרה בת קול עלי נהר הוא אמר כאהלים יצאה בת קול ואמרה נטע ה':"],[1,"רוח דרומית","קשה:"],[2,"לא עמנו היית באותה עצה","שגזר פרעה כל הבן הילוד היאורה בתמיה ודאי היית כדלקמן:"],[2,"ומי הושיבך אצל איתני עולם","שעתידים בניך לישב בלשכת הגזית והיינו דכתיב איתן מושבך וכי בין איתני עולם אתה יושב מי הזקיקך לכך:"],[4,"שמחיה עצמו בשם אל","עושה עצמו אלוה כמו פרעה וחירם:"],[4,"לשון אחר מי שמחיה עצמו","כלומר אוי להם לאותן בני אדם שמחיין ומעדנין עצמן בעוה\"ז ופורקין עול תורה מעל צוארם ומשמנין את עצמן:"],[4,"משמו אל","כשמשים הקב\"ה פדיון לעצמו ומשלם גמול לצדיקים לעתיד לבא. כך שמעתי:"],[4,"אוי לה לאומה שתמצא","אוי לה לאומה שתהיה באותן הימים שיעלה על דעתה לעכב ישראל:"],[4,"מי מטיל כסות בין לביא וכו'","לעכבן שלא יזדקקו זה לזה דמסוכן הוא כלומר מי הוא שיכול לעכב את ישראל והקב\"ה מכניסם:"],[5,"ציים","ספינות גדולות כמו (ישעיהו ל״ג:כ״א) וצי אדיר (בל) יעברנו:"],[5,"וצים מיד כתים אמר רב ליבא אספיר","דכתים היינו מקום ששמו כך:"],[5,"עד אשור מקטל קטילי","ומאשור ואילך משעבדי להו שעבודי:"],[5,"וצים מיד כתים וענו אשור","דקטלי להו וענו עבר דמשעבדי להן עד אשור:"],[5,"כתים","רומים כלומ' אותן אומות שהביא הקב\"ה בצים עתידין להרוג את כל האומות עד אשור ומאשור ואילך מניחין אותן ומשעבדין בהם (ומניחין אותן) ולעתיד קא מיירי:"],[6,"הן הנה היו לבני ישראל לא גרסינן אלא ה\"ג הנני הולך לעמי לכה איעצך אשר יעשה העם הזה לעמך עמך לעם הזה מבעי ליה","שהשיא עצה לבלק שנכשלו בה ישראל הן הנה היו לבני ישראל בדבר בלעם:"],[6,"ותולה קללתו בחברו","וכך בלעם לא רצה לתלות שפלות זה בבלק שיהא הוא צריך לבקש עצה היאך יכשלו בה ישראל אלא בישראל תלה השפלות לומר שהן צריכין לעצה שיכשלו בה בני מואב שלא תתקוף ידי מואב על ישראל והיינו דכתיב אשר יעשה העם הזה לעמך. מ\"ר. ל\"א תולה קללתו בחברו כלומר שתלה הכתוב קללה במואב ולא רצה לכתוב כלפי ישראל כמו שאמר בלעם הרשע:"],[7,"קלעים","אהלים של קלעים כמו שעושין בשוקים:"],[8,"בערבות מואב מהר שלג","שניר:"],[8,"כשהיה אומר לה","ישראל כלי פשתן זה בכמה זקנה אומרת לו דמי שוויו וילדה אומרת לו בפחות מכדי שוויו וכן עושין עד ב' או עד ג' פעמים:"],[9,"ברור לעצמך","כל תכשיטין שאתה רוצה:"],[9,"צרצרי","נודות:"],[9,"בוער בו","שהיה משתכר ובוער בו יצר הרע:"],[10,"השמיעי","הוי שומעת לתשמיש:"],[10,"פיעור","כך היתה עבודתו של פעור שמתריזים לפניו:"],[10,"","ה\"ג כלום מבקשין ממך אלא פיעור והוא עושה ושוב אומרת לו כפור בתורת משה רבך והוא עושה:"],[10,"וינזרו לבשת","סרו מדרכם והלכו אחר הבשת:"],[10,"כאהבם","מתוך תאות אהבתם לזנות היו משוקצים שכופרין בהקב\"ה:"],[12,"ותקראן","בגופן ותקראן [משמע] לשון מקרה:"],[13,"מאי רפידים","איידי דלעיל איפליגו ביה ר\"א ור' יהושע במשמעות דשטים נקיט נמי רפידים דפליגי ביה בכי האי גוונא:"],[13,"לא הפנו אבות אל בנים","להיטיב להם:"],[13,"מפני רפיון ידים","של תורה ומצות והכי נמי רפידים רפיון ידים הוא כלומר מפני שרפו ידים מן התורה בא עליהם עמלק:"],[15,"שכר כ\"ד אלפים מישראל","שהרגו בעצתו הלך ליטול מבלק ומזקני מדין:"],[15,"גמלא תבע קרני","כך בלעם שאל שכר ונהרג:"],[15,"גזו מיניה","חתכו ממנו:"],[16,"בלעם בן בעור הקוסם הרגו בחרב","ההוא קרא ביהושע כתיב:"],[16,"ולבסוף","שנתן עיניו לקלל את ישראל ניטלה ממנו נבואה ונעשה קוסם:"],[16,"מסגני ושילטא הואי","אשת סגנים ושרים היתה:"],[16,"אייזן לגברא נגר","זינתה למושכי חבל ספינה ל\"א נגרי חרשים:"]],[]],[["(יהושע יג, כב) הרגו בני ישראל [בחרב] אל חלליהם אמר רב שקיימו בו ארבע מיתות סקילה ושריפה הרג וחנק","א\"ל ההוא מינא לר' חנינא מי שמיע לך בלעם בר כמה הוה א\"ל מיכתב לא כתיב אלא מדכתיב (תהלים נה, כד) אנשי דמים ומרמה לא יחצו ימיהם בר תלתין ותלת שנין או בר תלתין וארבע א\"ל שפיר קאמרת לדידי חזי לי פנקסיה דבלעם והוה כתיב ביה בר תלתין ותלת שנין בלעם חגירא כד קטיל יתיה פנחס ליסטאה","א\"ל מר בריה דרבינא לבריה בכולהו לא תפיש למדרש לבר מבלעם הרשע דכמה דמשכחת ביה דרוש ביה","כתיב דואג וכתיב דוייג אמר ר' יוחנן בתחילה יושב הקב\"ה ודואג שמא יצא זה לתרבות רעה לאחר שיצא אמר ווי שיצא זה","(סימן גבור ורשע וצדיק חיל וסופר)","א\"ר יצחק מאי דכתיב (תהלים נב, ג) מה תתהלל ברעה הגבור חסד אל כל היום אמר לו הקב\"ה לדואג לא גבור בתורה אתה מה תתהלל ברעה לא חסד אל נטוי עליך כל היום","וא\"ר יצחק מאי דכתיב (תהלים נ, טז) ולרשע אמר אלהים מה לך לספר חוקי אמר לו הקב\"ה לדואג הרשע מה לך לספר חוקי כשאתה מגיע לפרשת מרצחים ופרשת מספרי לשון הרע מה אתה דורש בהם (תהלים נ, טז) ותשא בריתי עלי פיך אמר ר' אמי אין תורתו של דואג אלא משפה ולחוץ","ואמר רבי יצחק מאי דכתיב (תהלים נב, ח) ויראו צדיקים וייראו ועליו ישחקו בתחילה ייראו ולבסוף ישחקו","וא\"ר יצחק מאי דכתיב (איוב כ, טו) חיל בלע ויקיאנו מבטנו יורישנו אל אמר דוד לפני הקב\"ה רבש\"ע ימות דואג אמר לו חיל בלע ויקיאנו אמר לפניו מבטנו יורישנו אל","וא\"ר יצחק מאי דכתיב (תהלים נב, ז) גם אל יתצך לנצח אמר הקב\"ה לדוד ניתי דואג לעלמא דאתי אמר לפניו גם אל יתצך לנצח מאי דכתיב (תהלים נב, ז) יחתך ויסחך מאהל ושרשך מארץ חיים סלה אמר הקב\"ה לימרו שמעתא בי מדרשא משמיה אמר לפניו יחתך ויסחך מאהל ליהוי ליה בנין רבנן ושרשך מארץ חיים סלה","וא\"ר יצחק מאי דכתיב (ישעיהו לג, יח) איה סופר איה שוקל איה סופר את המגדלים איה סופר כל אותיות שבתורה איה שוקל ששוקל כל קלים וחמורים שבתורה איה סופר את המגדלים שהיה סופר שלש מאות הלכות פסוקות במגדל הפורח באויר","א\"ר ארבע מאה בעיי' בעו דואג ואחיתופל במגדל הפורח באויר [ולא איפשט להו חד] אמר רבא רבותא למבעי בעיי בשני דרב יהודה כולי תנויי בנזיקין ואנן קא מתנינן טובא בעוקצין","וכי הוה מטי רב יהודה אשה שכובשת ירק בקדירה ואמרי לה זיתים שכבשן בטרפיהן טהורים אמר הויות דרב ושמואל קא חזינא הכא ואנן קא מתנינן בעוקצין תלת סרי מתיבתא","ורב יהודה שליף מסאני ואתא מטרא ואנן צוחינן וליכא דמשגח בן אלא הקב\"ה ליבא בעי דכתיב (שמואל א טז, ז) וה' יראה ללבב","אמר רב משרשיא דואג ואחיתופל לא [הוו] סברי שמעתא מתקיף לה מר זוטרא מאן דכתיב ביה איה סופר איה שוקל איה סופר את המגדלים ואת אמרת לא הוו סברי שמעתא אלא דלא הוה סלקא להו שמעתא אליבא דהלכתא דכתיב (תהלים כה, יד) סוד ה' ליראיו","א\"ר אמי לא מת דואג עד ששכח תלמודו שנא' (משלי ה, כג) הוא ימות באין מוסר וברוב אולתו ישגה רב (אשי) אמר נצטרע שנאמר (תהלים עג, כז) הצמתה כל זונה ממך","כתיב התם (ויקרא כה, ל) לצמיתות ומתרגמינן לחלוטין ותנן אין בין מוסגר ומוחלט אלא פריעה ופרימה","(סימן שלשה ראו וחצי וקראו)","א\"ר יוחנן שלשה מלאכי חבלה נזדמנו לו לדואג אחד ששכח תלמודו ואחד ששרף נשמתו ואחד שפיזר עפרו בבתי כנסיות ובבתי מדרשות","(א\"ר) יוחנן דואג ואחיתופל לא ראו זה את זה דואג בימי שאול ואחיתופל בימי דוד","וא\"ר יוחנן דואג ואחיתופל לא חצו ימיהם תניא נמי הכי אנשי דמים ומרמה לא יחצו ימיהם כל שנותיו של דואג לא היו אלא שלשים וארבע ושל אחיתופל אינן אלא שלשים ושלש","וא\"ר יוחנן בתחלה קרא דוד לאחיתופל רבו ולבסוף קראו חבירו ולבסוף קראו תלמידו בתחילה קראו רבו (תהלים נה, יד) ואתה אנוש כערכי אלופי ומיודעי ולבסוף קראו חבירו (תהלים נה, טו) אשר יחדו נמתיק סוד בבית אלהים נהלך ברגש ולבסוף קראו תלמידו (תהלים מא, י) גם איש שלומי אשר בטחתי בו"],[[0,"הרגו אל חלליהם","מיתות הרבה משמע שתלאוהו והציתו אש תחת הצליבה וחתכו ראשו ונפל לתוך האש תלייה היינו חנק חתיכת הראש הרג כשנפל לארץ סקילה כשנפל לאור היינו שריפה:"],[1,"בר תלתין ותלת","ור\"ח לית ליה דר' סימאי דאמר לעיל (עמוד א) שלשה היו באותה עצה דפרעה בלעם ואיוב ויתרו דלר' סימאי בלעם חיה יותר מן מאתים ועשר שנים דהא היה בעצת פרעה דכל הבן הילוד היאורה תשליכוהו דלרבי סימאי כל אותן מאתים ועשר שנים שהיו ישראל בגלות מצרים עד מלחמת מדין חיה בלעם:"],[1,"חגירא","תרגום של פיסח:"],[1,"כד קטל יתיה פנחס ליסטאה","שר צבא ואפילו קטליה אחר כל המלחמה נקראת על שמו:"],[2,"בכולהו","מלכים והדיוטות:"],[2,"לא תפיש ותדרוש","לגנאי:"],[2,"לבר מבלעם","דכל מה דמשכחת ליה לגנאי דרוש:"],[3,"(שמא יצא זה לתרבות רעה) לאחר שיצא לתרבות רעה אמר ווי","לכך כתוב דוייג:"],[5,"א\"ל הקב\"ה לדואג והלא גבור אתה בתורה","למה תתהלל לספר לשון הרע על דוד:"],[5,"לא חסד תורה עליך","לא חכם בתורה אתה דכתיב (משלי לא) ותורת חסד על לשונה:"],[6,"מרצחים","שהרג נוב:"],[6,"עלי פיך","ולא בלב:"],[7,"בתחלה ייראו","הצדיקים היו יראים שלא ילמד אדם ממעשיו של דואג שהולך וחוטא ומצליח:"],[7,"ולבסוף","כשמת בחצי ימיו ושב גמולו בראשו ישחקו:"],[8,"חיל בלע ויקיאנו","המתן עד שתשכח תורתו:"],[8,"אמר לפניו ומבטנו יורישנו אל","אל תמתין לו עד שתשתכח אלא תמהר ותשכיחנו:"],[9,"בי מדרשא","מאהל זה בית המדרש:"],[9,"ושרשך מארץ חיים סלה","שורש שלו תכסח מארץ חיים דלא להוו ליה בנין רבנן:"],[10,"כל אותיות שבתורה","שהיה בקי בחסירות ויתירות:"],[10,"שוקל קלים וחמורים","יודע לדרוש בקל וחומר:"],[10,"במגדל הפורח באויר","מתג עליונה שלמעלה מן הלמ\"ד מפני מה כפופה למטה. לשון מ\"ר מפי השמועה. ל\"א במגדל הפורח באויר הנכנס לארץ העמים בשידה תיבה ומגדל אם הוא טמא אם לאו. ל\"א ג' מאות הלכות במגדל הפורח באויר לעשות כישוף להעמיד מגדל באויר כגון שלש מאות הלכות בנטיעות קשואין דאמרן בפירקין דלעיל (סנהדרין דף סח.) ולמורי נראה דה\"ג שלש מאות הלכות במגדל העומד [באויר] ומשנה אחת באהלות (פ\"ד משנה א) דמשתעי בהכי מגדל העומד באויר וטומאה בתוכה כלים שבתוכו טמאים וכן נראה לר':"],[11,"רבותא למבעא בעיי","וללמוד תורה רחמנא לבא בעי דהא בשני דרב יהודה כולהו תנויי בסדר נזיקין היה כל הגמרא שלהן לא הוה אלא בסדר נזיקין שלא היו מרבין כל כך [לדרוש]:"],[12,"האשה שכובשת ירק בקדירה","לא אשכחתיה במסכת עוקצין:"],[12,"שכובשת ירק","בחומץ או בציר טהורים דאין מקבלין טומאה ע\"י עוקצין שאם נגע טומאה בשרשיו העלין טהורין שאין נעשין יד לעלין מאחר שכבשם שאין מניחין לשם אלא למראה:"],[12,"זיתים שכבשן בטרפיהן","איתא במסכת עוקצין (פ\"ב מ\"א):"],[12,"טרפיהן","עלין שלהן טהורין הזיתים שאין נעשין להם בית יד להכניס להם טומאה:"],[12,"הויות דרב ושמואל קא חזינא הכא","דלא הוה ידע מאי טעמא הן טהורין:"],[12,"תליסר מתיבתא","י\"ג ישיבות שאנו עוסקין כולן במסכת עוקצין ויודעין אותה יפה ואפי' הכי בהם היו חסידים יותר ממנו דאלו רב יהודה כו':"],[14,"לא סבירי","לא היו יודעין הלכה לפרשה כתקנה בטעמא:"],[14,"דלא סלקא להו שמעתתא כו'","שלא זכו לקבוע הלכה כמותן:"],[16,"ומתרגמינן לחלוטין","ואנן תנן לשון חלוטין גבי מצורע:"],[21,"אלופי","היינו רבי:"]],[]],[["אוכל לחמי הגדיל עלי עקב","אמר רב יהודה אמר רב לעולם אל יביא אדם עצמו לידי נסיון שהרי דוד מלך ישראל הביא עצמו לידי נסיון ונכשל אמר לפניו רבש\"ע מפני מה אומרים אלהי אברהם אלהי יצחק ואלהי יעקב ואין אומרים אלהי דוד אמר אינהו מינסו לי ואת לא מינסית לי אמר לפניו רבש\"ע בחנני ונסני שנאמר (תהלים כו, ב) בחנני ה' ונסני וגו'","אמר מינסנא לך ועבידנא מילתא בהדך דלדידהו לא הודעתינהו ואילו אנא קא מודענא לך דמנסינא לך בדבר ערוה מיד (שמואל ב יא, ב) ויהי לעת הערב ויקם דוד מעל משכבו וגו'","אמר רב יהודה שהפך משכבו של לילה למשכבו של יום ונתעלמה ממנו הלכה אבר קטן יש באדם משביעו רעב ומרעיבו שבע","(שמואל ב יא, ב) ויתהלך על גג בית המלך וירא אשה רוחצת מעל הגג והאשה טובת מראה מאד בת שבע הוה קא חייפא רישא תותי חלתא אתא שטן אידמי ליה כציפרתא פתק ביה גירא פתקה לחלתא איגליה וחזייה","מיד (שמואל ב יא, ג) וישלח דוד וידרוש לאשה ויאמר הלא זאת בת שבע בת אליעם אשת אוריה החתי וישלח דוד מלאכים ויקחה ותבא אליו וישכב עמה והיא מתקדשת מטומאתה ותשב אל ביתה והיינו דכתיב (תהלים יז, ג) בחנת לבי פקדת לילה צרפתני בל תמצא זמותי בל יעבר פי אמר איכו זממא נפל בפומיה דמאן דסני לי ולא אמר כי הא מילתא","דרש רבא מאי דכתיב (תהלים יא, א) למנצח לדוד בה' חסיתי איך תאמרו לנפשי נודי הרכם צפור אמר דוד לפני הקב\"ה רבש\"ע מחול לי על אותו עון שלא יאמרו הר שבכם צפור נדדתו","דרש רבא מאי דכתיב (תהלים נא, ו) לך לבדך חטאתי והרע בעיניך עשיתי למען תצדק בדברך תזכה בשפטך אמר דוד לפני הקב\"ה גליא וידיעא קמך דאי בעיא למכפייה ליצרי הוה כייפינא אלא אמינא דלא לימרו עבדא זכי למריה","דרש רבא מאי דכתיב (תהלים לח, יח) כי אני לצלע נכון ומכאובי נגדי תמיד ראויה היתה בת שבע בת אליעם לדוד מששת ימי בראשית אלא שבאה אליו במכאוב וכן תנא דבי רבי ישמעאל ראויה היתה לדוד בת שבע בת אליעם אלא שאכלה פגה","דרש רבא מאי דכתיב (תהלים לה, טו) ובצלעי שמחו ונאספו נאספו עלי נכים [ולא ידעתי] קרעו ולא דמו אמר דוד לפני הקב\"ה רבש\"ע גלוי וידוע לפניך שאם היו קורעין בשרי לא היה דמי שותת","ולא עוד אלא בשעה שהם עוסקין בארבע מיתות ב\"ד פוסקין ממשנתן ואומרים לי דוד הבא על אשת איש מיתתו במה אמרתי להם הבא על אשת איש מיתתו בחנק ויש לו חלק לעוה\"ב אבל המלבין פני חבירו ברבים אין לו חלק לעולם הבא","אמר רב יהודה אמר רב אפילו בשעת חליו של דוד קיים שמנה עשרה עונות שנאמר (תהלים ו, ז) יגעתי באנחתי אשחה בכל לילה מטתי בדמעתי ערשי אמסה ואמר רב יהודה אמר רב בקש דוד לעבוד ע\"ז שנאמר (שמואל ב טו, לב) ויהי דוד בא עד הראש אשר ישתחוה שם לאלהים ואין ראש אלא ע\"ז שנאמר (דניאל ב, לב) והוא צלמא רישיה די דהב טב","(שמואל ב טו, לב) והנה לקראתו חושי הארכי קרוע כתנתו ואדמה על ראשו אמר לו לדוד יאמרו מלך שכמותך יעבוד ע\"ז אמר לו מלך שכמותי יהרגנו בנו מוטב יעבוד ע\"ז ואל יתחלל שם שמים בפרהסיא","אמר מאי טעמא קנסיבת יפת תואר א\"ל יפת תואר רחמנא שרייה א\"ל לא דרשת סמוכין דסמיך ליה (דברים כא, יח) כי יהיה לאיש בן סורר ומורה כל הנושא יפת תואר יש לו בן סורר ומורה","דרש ר' דוסתאי דמן בירי למה דוד דומה לסוחר כותי אמר דוד לפני הקב\"ה רבש\"ע (תהלים יט, יג) שגיאות מי יבין [א\"ל] שביקי לך ומנסתרות נקני שביקי לך גם מזדים חשוך עבדך שביקי לך אל ימשלו בי אז איתם דלא לישתעו בי רבנן שביקי לך","ונקיתי מפשע רב שלא יכתב סרחוני אמר לו א\"א ומה יו\"ד שנטלתי משרי עומד וצווח כמה שנים עד שבא יהושע והוספתי לו שנאמר (במדבר יג, טז) ויקרא משה להושע בן נון יהושע כל הפרשה כולה עאכ\"ו","ונקיתי מפשע רב אמר לפניו רבש\"ע מחול לי על אותו עון כולו אמר כבר עתיד שלמה בנך לומר בחכמתו (משלי ו, כז) היחתה איש אש בחיקו ובגדיו לא תשרפנה אם יהלך איש על הגחלים ורגליו לא תכוינה כן הבא על אשת רעהו לא ינקה כל הנוגע בה א\"ל כל הכי נטרד ההוא גברא א\"ל קבל עליך יסורין קבל עליו","אמר רב יהודה אמר רב ששה חדשים נצטרע דוד ונסתלקה הימנו שכינה ופירשו ממנו סנהדרין נצטרע דכתיב (תהלים נא, ט) תחטאני באזוב ואטהר תכבסני ומשלג אלבין נסתלקה הימנו שכינה דכתיב (תהלים נא, יד) השיבה לי ששון ישעך ורוח נדיבה תסמכני ופרשו ממנו סנהדרין דכתי' (תהלים קיט, עט) ישובו לי יראיך וגו' ששה חדשים מנלן דכתי' (מלכים א ב, יא) והימים אשר מלך דוד על ישראל ארבעים שנה"],[[0,"אוכל לחמי","לומד תורתי:"],[3,"שהפך משכבו של לילה לשל יום","שהיה משמש מטתו ביום כדי שיהא שבע מתשמיש ולא יהרהר אחר אשה כל היום:"],[3,"ונתעלמה ממנו [הלכה]","שהמשביע אברו בתשמיש רעב ומרבה תאוה:"],[4,"","ה\"ג מתהלך על גג המלך ולא גרסינן והיינו:"],[4,"חלתא","כוורת:"],[4,"פתיק [ביה] גירא","בכוורת כלומר שהכה ושברה ל\"א פתחה שברה ונפתחה:"],[5,"מתקדשת מטומאתה","אותה שעה פסק טומאתה ולא בא עליה כשהיא נדה:"],[5,"פקדת לילה","על מעשה לילה פקדתני אם אוכל לעמוד בנסיון של דבר עבירה:"],[5,"צרפתני בל תמצא","חשבת לצרפני ולא מצאתני נקי:"],[5,"(זמותי ב 'ר יעבר פי) איכו זממא נפל","מי יתן והיה בפי רסן ואפשר לעכב את דברי שלא אומר דבר זה [של] בחנני:"],[6,"הר שבכם","מלך שלכם:"],[6,"צפור נדדתו","דעל ידי צפור נטרד כדאמר אדמי ליה כצפור:"],[7,"למריה","העבד נצחו לאדוניו בתוכחתו:"],[8,"כי אני לצלע נכון","אותו צלע היה נכון לי:"],[8,"שאכלה פגה","שקפץ את השעה ליזקק ע\"י עבירה:"],[9,"נאספו עלי נכים","בעלי מומין כמו פרעה נכה (מלבים ב כג) והיו מלעיגים עלי ואני כלא . יודע ל\"א ולא ידעתי לא הייתי יודע כשמלעיגים כלומר פתאום בא עלי אותו עון שלא ידעתי (עד) שניתן פתחון פה לביישני:"],[10,"","הכי גרסינן בשעה שעוסקין במיתות בית דין אומרים הבא על אשת איש מיתתו וכו':"],[11,"י\"ח עונות","לי\"ח נשיו שלא לעגנן:"],[11,"באנחתי אשחה","אפילו בשעת אנחתי אשחה בכל לילה:"],[11,"מטתי","תשמיש המטה ענין סחי ומאוס (איכה ג׳:מ״ה) קרי ליה:"],[11,"בדמעתי ערשי אמסה","שבשעת דמעתי אני ממאיס את מטתי בתשמיש:"],[12,"יאמרו מלך שכמותי","חסיד שכמותי הרגו בנו ויהו מתרעמין על מדותיו של הקב\"ה ונמצא שם שמים מתחלל בפרהסיא:"],[12,"מוטב אעבוד ע\"ז","ואחלל את השם אני לבדי ולא יחללו [אותו] כל העם:"],[13,"אמר ליה","חושי הארכי לדוד הקב\"ה לא עביד דינא בלא דינא שמעמיד בנך להרגך דאת מאי טעמא נסבת יפת תואר דאמו של אבשלום מעכה בת תלמי מלך גשור (שמואל ב ג) ותפסה דוד במלחמה דאין לומר בעבירה באה לו דהא כתיב (מלכים א טו) רק בדבר אוריה החתי:"],[14,"סוחר כותי","דרכו לפנות את סחורתו מעט מעט להעמידה על דמים מועטים:"],[14,"שגיאות מי יבין","מי יכול להשמר משגגות:"],[14,"אמר לו","הקב\"ה:"],[14,"שביקא לך","מחול לך:"],[14,"נסתרות","[מזיד] של צנעה:"],[14,"זדים","מזיד של פרהסיא:"],[14,"ה\"ג אל ימשלו בי דלא לישתעו בי רבנן","והיינו אל ימשלו לשון משל שלא ידרשו בחטאתי חכמי הדורות ואז איתם:"],[15,"שלא יכתב סורחני","שתמחוק אותה פרשה מן המקרא וישתכח הדבר לעולמים:"],[15,"כל הפרשה","שכתובה כבר שעשית אותו חטא:"],[15,"על אחת כמה וכמה","שלא תעקור:"],[17,"תחטאני באזוב","מכלל שהיה צריך טהרת אזוב כמצורע:"]],[]],[["בחברון מלך שבע שנים ובירושלים מלך שלשים ושלש שנים וכתיב (שמואל ב ה, ה) בחברון מלך על יהודה שבע שנים וששה חדשים וגו' והני ששה חדשים לא קחשיב ש\"מ נצטרע","אמר לפניו רבש\"ע מחול לי על אותו עון מחול לך (תהלים פו, יז) עשה עמי אות לטובה ויראו שונאי ויבושו כי אתה ה' עזרתני ונחמתני א\"ל בחייך איני מודיע אבל אני מודיע בחיי שלמה בנך","בשעה שבנה שלמה את בית המקדש ביקש להכניס ארון לבית קדשי הקדשים דבקו שערים זה בזה אמר עשרים וארבעה רננות ולא נענה אמר (תהלים כד, ז) שאו שערים ראשיכם והנשאו פתחי עולם ויבא מלך הכבוד מי זה מלך הכבוד ה' עזוז וגבור ה' גבור מלחמה ונאמר (תהלים כד, ט) שאו שערים ראשיכם ושאו פתחי עולם ויבא מלך הכבוד וגו' ולא נענה","כיון שאמר (דברי הימים ב ו, מב) ה' אלהים אל תשב פני משיחך זכרה לחסדי דויד עבדך מיד נענה באותה שעה נהפכו פני שונאי דוד כשולי קדירה וידעו כל ישראל שמחל לו הקב\"ה על אותו העון","גחזי דכתיב וילך אלישע דמשק להיכא אזל א\"ר יוחנן שהלך להחזיר גחזי בתשובה ולא חזר אמר לו חזור בך אמר לו כך מקובלני ממך החוטא ומחטיא את הרבים אין מספיקין בידו לעשות תשובה","מאי עבד איכא דאמרי אבן שואבת תלה לחטאת ירבעם והעמידה בין שמים לארץ ואיכא דאמרי שם חקק בפיה והיתה מכרזת ואומרת אנכי ולא יהיה לך","וא\"ד רבנן דחה מקמיה שנאמר (מלכים ב ו, א) ויאמרו בני הנביאים אל אלישע הנה [נא] המקום אשר אנחנו יושבים שם לפניך צר ממנו מכלל דעד השתא לא הוו (פיישי) [צר]","תנו רבנן לעולם תהא שמאל דוחה וימין מקרבת לא כאלישע שדחפו לגחזי בשתי ידים [ולא כרבי יהושע בן פרחיה שדחפו ליש\"ו בשתי ידים]","גחזי דכתיב (מלכים ב ה, כג) ויאמר נעמן הואל וקח ככרים (ויפצר) [ויפרץ] בו ויצר ככרים כסף וגו' ויאמר אליו אלישע מאין גחזי ויאמר לא הלך עבדך אנה ואנה ויאמר אליו לא לבי הלך כאשר הפך איש מעל מרכבתו לקראתך העת לקחת את הכסף ולקחת בגדים וזיתים וכרמים וצאן ובקר ועבדים ושפחות ומי שקל כולי האי כסף ובגדים הוא דשקל","אמר רבי יצחק באותה שעה היה אלישע יושב ודורש בשמונה שרצים נעמן שר צבא מלך ארם היה מצורע אמרה ליה ההיא רביתא דאישתבאי מארעא ישראל אי אזלת לגבי אלישע מסי לך כי אתא א\"ל זיל טבול בירדן א\"ל אחוכי קא מחייכת בי אמרי ליה הנהו דהוו בהדיה מאי נפקא לך מינה זיל נסי אזל וטבל בירדנא ואיתסי אתא אייתי ליה כל הני דנקיט לא צבי לקבולי מיניה גחזי איפטר מקמיה אלישע אזל שקל מאי דשקל ואפקיד","כי אתא חזייה אלישע לצרעת דהוה פרחא עילויה רישיה א\"ל רשע הגיע עת ליטול שכר שמנה שרצים וצרעת נעמן תדבק בך ובזרעך עד עולם ויצא מלפניו מצורע כשלג: (מלכים ב ז, ג) וארבעה אנשים היו מצורעים פתח השער אמר ר' יוחנן גחזי ושלשה בניו","[הוספה מחסרונות הש\"ס: רבי יהושע בן פרחיה מאי הוא כדקטלינהו ינאי מלכא לרבנן אזל רבי יהושע בן פרחיה ויש\"ו לאלכסנדריא של מצרים כי הוה שלמא שלח לי' שמעון בן שטח מני ירושלים עיר הקודש ליכי אלכסנדרי' של מצרים אחותי בעלי שרוי בתוכך ואנכי יושבת שוממה","קם אתא ואתרמי ליה ההוא אושפיזא עבדו ליה יקרא טובא אמר כמה יפה אכסניא זו אמר ליה רבי עיניה טרוטות אמר ליה רשע בכך אתה עוסק אפיק ארבע מאה שיפורי ושמתיה","אתא לקמיה כמה זמנין אמר ליה קבלן לא הוי קא משגח ביה יומא חד הוה קא קרי קריאת שמע אתא לקמיה סבר לקבולי אחוי ליה בידיה הוא סבר מידחא דחי ליה אזל זקף לבינתא והשתחוה לה אמר ליה הדר בך אמר ליה כך מקובלני ממך כל החוטא ומחטיא את הרבים אין מספיקין בידו לעשות תשובה ואמר מר יש\"ו כישף והסית והדיח את ישראל:]","תניא א\"ר שמעון בן אלעזר יצר תינוק ואשה תהא שמאל דוחה וימין מקרבת","ת\"ר ג' חלאים חלה אלישע אחד שגירה דובים בתינוקות ואחד שדחפו לגחזי בשתי ידים ואחד שמת בו [שנא' (מלכים ב יג, יד) ואלישע חלה את חליו וגו']","עד אברהם לא היה זקנה כל דחזי לאברהם אמר האי יצחק כל דחזי ליצחק אמר האי אברהם בעא אברהם רחמי דליהוי ליה זקנה שנאמר (בראשית כד, א) ואברהם זקן בא בימים עד יעקב לא הוה חולשא בעא רחמי והוה חולשא שנאמר (בראשית מח, א) ויאמר ליוסף הנה אביך חולה עד אלישע לא הוה איניש חליש דמיתפח ואתא אלישע ובעא רחמי ואיתפח שנא' (מלכים ב יג, יד) ואלישע חלה את חליו אשר ימות בו:","\u0001מתני׳\u0002 דור המבול אין להם חלק לעוה\"ב ואין עומדין בדין שנא' (בראשית ו, ג) לא ידון רוחי באדם לעולם לא דין ולא רוח דור הפלגה אין להם חלק לעולם הבא שנאמר (בראשית יא, ח) ויפץ ה' אותם משם על פני כל הארץ (וכתיב ומשם הפיצם) ויפץ ה' אותם בעוה\"ז ומשם הפיצם ה' לעולם הבא אנשי סדום אין להם חלק לעולם הבא שנא' (בראשית יג, יג) ואנשי סדום רעים וחטאים לה' מאד רעים בעולם הזה וחטאים לעולם הבא אבל עומדין בדין","ר' נחמיה אומר אלו ואלו אין עומדין בדין שנאמר (תהלים א, ה) על כן לא יקומו"],[[0,"בחברון מלך שבע שנים וששה חדשים","מדהכא חשיב להו ובאידך קרא לא חשיב להו ש\"מ לא היה מלכותו שלימה שנצטרע אותן ו' חדשים:"],[1,"","ה\"ג אבל בחיי בנך אני מודיע ולא גרסינן לך:"],[2,"כ\"ד רננות","בין תפלה תחנה ורנה איכא כ\"ד:"],[4,"","וילך אלישע דמשק להיכא אזל:"],[5,"שואבת","מגבהת מתכת בלא נגיעה כעין אותה שלועזין קלאמניס\"ה בלע\"ז ועל ידי אותה אבן העמיד עגלים של ירבעם באויר:"],[6,"רבנן דחה מקמיה","התלמידים דחה מישיבתו של אלישע:"],[6,"צר ממנו","מכלל דעד האידנא לא הוה צר:"],[8,"הואל וקח","השבע שאלישע שלחך:"],[8,"ויפצר בו","גחזי: העת לקחת את הכסף והבגדים וגו':"],[8,"","שמנה דברים קא חשיב בהאי קרא:"],[8,"וגחזי מי שקל כולי האי","מנעמן כסף ובגדים הוא דשקל דכתיב ויצר ככרים וגו':"],[9,"אותה שעה","היה אלישע עוסק בפרק שמונה שרצים אמר לו הגיע עת ליטול שכר פרק שמונה שרצים שעסקתי וכו' ולהכי כתב בהאי קרא שמנה דברים כנגד אותו פרק כלומר בכסף ובגדים שקבלת ממנו מנעמן סבור אתה לקנות דברים הללו להיותם לך שכר שמונה שרצים:"],[11,"[הוספה מחסרונות הש\"ס: ינאי מלכא","כהן גדול היה וקטל כולהו רבנן במסכת קידושין:"],[11,"שמעון בן שטח","אחי אשתו של ינאי המלך במסכת ברכות והוא לא ברח:"],[12,"טרוטות","עגולות:"],[13,"אחוי ליה","רבי יהושע בן פרחיה בידיה דלקבלוהו:]"],[14,"יצר","תאותו אם מרחיקה ממנו לגמרי ממעט ישיבת עולם ואם מקרבה לגמרי בא לידי איסור שאינו יכול לכבוש יצרו מדבר עבירה:"],[14,"תינוק ואשה","דעתן קלה ואם תדחה אותם מטרדן מן העולם:"],[15,"חלה","חד חליו תרי אשר ימות בו תלת:"],[16,"בעא רחמי דלהוי חולשא","כדי שיהא פנאי לבניו לבא כל אחד ואחד ממקומו להיות עליו בשעת מיתה שכיון שרואין שנפל למטה יודעין שימות ומתקבצין ובאין:"],[16,"מתפח","מתרפא:"],[17,"מתני' לא ידון רוחי לא דין ולא רוח","שאין עומדין בדין ואין להם רוח להיות עם הצדיקים שיש להם חלק:"],[17,"ויפץ [ה' אותם ומשם הפיצם","ויפץ] בעולם הזה ומשם הפיצם בעולם הבא:"],[18,"אלו ואלו","אנשי דור המבול ואנשי סדום ובחדא פליג ר' נחמיה:"]],[]],[["רשעים במשפט וחטאים בעדת צדיקים על כן לא יקומו רשעים במשפט זה דור המבול וחטאים בעדת צדיקים אלו אנשי סדום אמרו לו אינם עומדין בעדת צדיקים אבל עומדין בעדת רשעים","(מרגלים אין להם חלק לעולם הבא שנאמר (במדבר יד, לז) וימותו האנשים מוציאי דבת הארץ רעה במגפה לפני ה' וימותו בעולם הזה במגפה לעולם הבא)","דור המדבר אין להם חלק לעולם הבא ואין עומדין בדין שנאמר (במדבר יד, לה) במדבר הזה יתמו ושם ימותו דברי רבי עקיבא ר' אליעזר אומר עליהם הוא אומר (תהלים נ, ה) אספו לי חסידי כורתי בריתי עלי זבח","עדת קרח אינה עתידה לעלות שנאמר (במדבר טז, לג) ותכס עליהם הארץ בעולם הזה ויאבדו מתוך הקהל לעולם הבא דברי ר\"ע ר\"א אומר עליהם הוא אומר (שמואל א ב, ו) ה' ממית ומחיה מוריד שאול ויעל:","\u0001גמ׳\u0002 ת\"ר דור המבול אין להם חלק לעולם הבא שנאמר (בראשית ז, כג) וימח את כל היקום אשר על פני האדמה וימח את כל היקום בעולם הזה וימחו מן הארץ לעולם הבא דברי ר\"ע ר\"י בן בתירא אומר לא חיין ולא נדונין שנאמר (בראשית ו, ג) לא ידון רוחי באדם לעולם לא דין ולא רוח דבר אחר לא ידון רוחי שלא תהא נשמתן חוזרת לנדנה","ר' מנחם בר יוסף אומר אפילו בשעה שהקב\"ה מחזיר נשמות לפגרים מתים נשמתן קשה להם בגיהנם שנאמר (ישעיהו לג, יא) תהרו חשש תלדו קש רוחכם אש תאכלכם","ת\"ר דור המבול לא נתגאו אלא בשביל טובה שהשפיע להם הקב\"ה ומה כתיב בהם (איוב כא, ט) בתיהם שלום מפחד ולא שבט אלוה עליהם וכתיב (איוב כא, י) שורו עבר ולא יגעיל תפלט פרתו ולא תשכל וכתיב (איוב כא, יא) ישלחו כצאן עויליהם וילדיהם ירקדון וכתיב (איוב כא, יב) ישאו בתוף וכנור וישמחו לקול עוגב וכתיב יבלו ימיהם בטוב ושנותם בנעימים וכתיב וברגע שאול יחתו","והיא גרמה שאמרו לאל (איוב כא, יד) סור ממנו ודעת דרכיך לא חפצנו מה שדי כי נעבדנו ומה נועיל כי נפגע בו אמרו כלום צריכין אנו לו אלא לטיפה של גשמים יש לנו נהרות ומעינות שאנו מסתפקין מהן אמר הקב\"ה בטובה שהשפעתי להן בה מכעיסין אותי ובה אני דן אותם שנאמר (בראשית ו, יז) ואני הנני מביא את המבול מים","ר' יוסי אמר דור המבול לא נתגאו אלא בשביל גלגל העין שדומה למים [שנאמר (בראשית ו, ב) ויקחו להם נשים מכל אשר בחרו] לפיכך דן אותן במים שדומה לגלגל העין שנאמר (בראשית ז, יא) נבקעו כל מעינות תהום רבה וארבות השמים נפתחו","א\"ר יוחנן דור המבול ברבה קלקלו וברבה נידונו ברבה קלקלו שנאמר (בראשית ו, ה) וירא ה' כי רבה רעת האדם וברבה נידונו שנאמר (בראשית ז, יא) כל מעינות תהום רבה א\"ר יוחנן שלשה נשתיירו מהם בלועה דגדר וחמי טבריא ועיניא רבתי דבירם","(בראשית ו, יב) כי השחית כל בשר את דרכו על הארץ א\"ר יוחנן מלמד שהרביעו בהמה על חיה וחיה על בהמה והכל על אדם ואדם על הכל א\"ר אבא בר כהנא וכולם חזרו חוץ מתושלמי","(בראשית ו, ג) ויאמר ה' לנח קץ כל בשר בא לפני א\"ר יוחנן בא וראה כמה גדול כחה של חמס שהרי דור המבול עברו על הכל ולא נחתם עליהם גזר דינם עד שפשטו ידיהם בגזל שנאמר (בראשית ו, יג) כי מלאה הארץ חמס מפניהם והנני משחיתם את הארץ וכתיב (יחזקאל ז, יא) החמס קם למטה רשע לא מהם ולא מהמונם ולא מהמהם ולא נה בהם","א\"ר אלעזר מלמד שזקף עצמו כמקל ועמד לפני הקב\"ה ואמר לפניו רבש\"ע לא מהם ולא מהמונם ולא מהמהם ולא נה בהם","(ואף על נח נחתם גזר דין שנא' ולא נח בהם) תנא דבי ר' ישמעאל אף על נח נחתך גזר דין אלא שמצא חן בעיני ה' שנאמר (בראשית ו, ז) נחמתי כי עשיתם ונח מצא חן בעיני ה'","(בראשית ו, ו) וינחם ה' כי עשה את האדם בארץ כי אתא רב דימי אמר אמר הקב\"ה יפה עשיתי שתקנתי להם קברות בארץ מאי משמע כתיב הכא וינחם ה' וכתיב התם (בראשית נ, כא) וינחם אותם וידבר על לבם","ואיכא דאמרי לא יפה עשיתי שתקנתי להם קברות בארץ כתיב הכא וינחם וכתיב התם (שמות לב, יד) וינחם ה' על הרעה אשר דבר לעשות לעמו","(בראשית ו, ט) אלה תולדות נח [נח איש צדיק תמים היה בדורותיו] א\"ר יוחנן בדורותיו ולא בדורות אחרים וריש לקיש אמר בדורותיו כ\"ש בדורות אחרים","א\"ר חנינא משל דרבי יוחנן למה הדבר דומה לחבית של יין שהיתה מונחת במרתף של חומץ במקומה ריחה נודף שלא במקומה אין ריחה נודף א\"ר אושעיא משל דריש לקיש למה הדבר דומה לצלוחית של פלייטון שהיתה מונחת במקום הטנופת במקומה ריחה נודף וכ\"ש במקום הבוסם","(בראשית ז, כג) וימח את כל היקום אשר על פני האדמה אם אדם חטא בהמה מה חטאה","תנא משום רבי יהושע בן קרחה משל לאדם שעשה חופה לבנו והתקין מכל מיני סעודה לימים מת בנו עמד (ובלבל) [ופזר] את חופתו אמר כלום עשיתי אלא בשביל בני עכשיו שמת חופה למה לי אף הקב\"ה אמר כלום בראתי בהמה וחיה אלא בשביל אדם עכשיו שאדם חוטא בהמה וחיה למה לי","(בראשית ז, כב) מכל אשר בחרבה מתו ולא דגים שבים","דרש ר' יוסי דמן קסרי מאי דכתיב (איוב כד, יח) קל הוא על פני מים תקולל חלקתם בארץ מלמד שהיה נח הצדיק מוכיח בהם ואומר להם עשו תשובה ואם לאו הקב\"ה מביא עליכם את המבול ומקפה נבלתכם על המים כזיקין שנאמר קל הוא על פני מים ולא עוד אלא שלוקחין מהם קללה לכל באי עולם שנאמר (איוב כד, יח) תקולל חלקתם בארץ","לא יפנה דרך כרמים מלמד שהיו מפנים דרך כרמים אמר לו ומי מעכב אמר להם פרידה אחת יש לי להוציא מכם"],[[0,"רשעים דור המבול","דכתיב [בהו] כי רבה רעת האדם (בראשית ו׳:ה׳):"],[0,"חטאים אנשי סדום","דכתיב בהו רעים וחטאים (שם יג):"],[0,"אבל עומדים הם כו'","שחיין ונדונים:"],[5,"גמ' נשמתן קשה להם בגיהנם","נשמת עצמן שרפתן דכתיב רוחכם אש תאכלכם (ישעיהו לג):"],[8,"בשביל גלגל העין","שרואין טובתן שלימה והיו גובהין עיניהם ומנאפין אחר עיניהם:"],[8,"במים","שדומה לגלגל העין מעינות שנובעין ממקום קטן כמו עין:"],[9,"שלשה נשתיירו","מאותן מעינות של דור המבול שהיו חמין כדאמר לקמן ברותחין קלקלו ברותחין נדונו:"],[10,"וכולן חזרו","להזדווג עם מיניהם:"],[10,"חוץ מתושלמי","עוף הוא שאוחז עדיין תרבות רעה שמזדווג עם הכל. תושלמי עוף אחד ובמסכת חולין (דף סב:) גבי שמונה ספיקות איתא והרנוגא תושלמי ומרדא ודרכו של אותו עוף להרביע כל הבריות:"],[12,"שזקף","החמס עצמו כמקל והיינו החמס קם למטה רשע:"],[12,"לא מהם","אין תועלת לא בהם ולא בהמונם ולא במשאם:"],[12,"מהמהם","אשטרי\"א בלע\"ז:"],[13,"כי נחמתי כי עשיתים ונח","סמוכין דריש:"],[14,"יפה עשיתי וכו'","שאיבדתי דרך רשעים כזה:"],[15,"לא יפה עשיתי","דאפשר היו חוזרין:"],[16,"כל שכן","אילו הוה בדורות אחרים היה צדיק יותר:"],[17,"פלייטון","בושם שריחו נודף ואינו אפרסמון:"],[21,"מקיפה","מציף כמו ויצף הברזל דמתרגמינן וקפא (מלכים ב ו׳:ו׳):"],[21,"כזיקין","נודות:"],[22,"לא יפנה דרך כרמים אמרו לו ומי מעכב","[מיד] שאינו עושה אם יש בידו כח לעשות כך:"],[22,"[פרידה] אחת יש לי להוציא מכם","מתושלח הצדיק ימות קודם ולא יהיה נדון עמכם:"]],[]],[["א\"כ לא נפנה דרך כרמים","דרש רבא מאי דכתיב (איוב יב, ה) לפיד בוז לעשתות שאנן נכון למועדי רגל מלמד שהיה נח הצדיק מוכיח אותם ואמר להם דברים שהם קשים כלפידים והיו (בוזים) [מבזין] אותו אמרו לו זקן תיבה זו למה אמר להם הקב\"ה מביא עליכם את המבול אמרו מבול של מה אם מבול של אש יש לנו דבר אחר ועליתה שמה ואם של מים הוא מביא אם מן הארץ הוא מביא יש לנו עששיות של ברזל שאנו מחפין בהם את הארץ ואם מן השמים הוא מביא יש לנו דבר ועקב שמו ואמרי לה עקש שמו","אמר להם הוא מביא מבין עקבי רגליכם שנאמר (איוב יב, ה) נכון למועדי רגל תניא מימי המבול קשים כשכבת זרע שנאמר נכון למועדי רגל אמר רב חסדא ברותחין קלקלו בעבירה וברותחין נידונו כתיב הכא (בראשית ח, א) וישכו המים וכתיב התם (אסתר ז, י) וחמת המלך שככה","(בראשית ז, י) ויהי לשבעת הימים ומי המבול היו על הארץ מה טיבם של שבעת הימים","אמר רב אלו ימי אבילות של מתושלח ללמדך שהספדן של צדיקים מעכבין את הפורענות לבא דבר אחר לשבעת ששינה עליהם הקב\"ה סדר בראשית שהיתה חמה יוצאת ממערב ושוקעת במזרח דבר אחר שקבע להם הקב\"ה זמן גדול ואח\"כ זמן קטן ד\"א לשבעת הימים שהטעימם מעין העולם הבא כדי שידעו מה טובה מנעו מהן","(בראשית ז, ב) מכל הבהמה הטהורה תקח לך שבעה שבעה איש ואשתו אישות לבהמה מי אית לה א\"ר שמואל בר נחמני א\"ר יונתן מאותם שלא נעבדה בהם עבירה","מנא ידע אמר רב חסדא שהעבירן לפני התיבה כל שהתיבה קולטתו בידוע שלא נעבדה בהם עבירה וכל שאין התיבה קולטתו בידוע שנעבדה בה עבירה רבי אבהו אמר מאותן הבאין מאיליהן","(בראשית ו, יד) עשה לך תיבת עצי גופר מאי גופר אמר רב אדא אמרי דבי ר' שילא זו מבליגה ואמרי לה גולמיש","צוהר תעשה לתיבה א\"ר יוחנן אמר לו הקב\"ה לנח קבע בה אבנים טובות ומרגליות כדי שיהיו מאירות לכם כצהרים","(בראשית ו, טז) ואל אמה תכלנה מלמעלה דבהכי [הוא] דקיימא","(בראשית ו, טז) תחתיים שנים ושלישים תעשה תנא תחתיים לזבל אמצעיים לבהמה עליונים לאדם","(בראשית ח, ז) וישלח את העורב אמר ר\"ל תשובה ניצחת השיבו עורב לנח אמר לו רבך שונאני ואתה שנאתני רבך שונאני מן הטהורין שבעה מן הטמאים שנים ואתה שנאתני שאתה מניח ממין שבעה ושולח ממין שנים אם פוגע בי שר חמה או שר צנה לא נמצא עולם חסר בריה אחת או שמא לאשתי אתה צריך","אמר לו רשע במותר לי נאסר לי בנאסר לי לא כ\"ש","ומנלן דנאסרו דכתיב (בראשית ו, יח) ובאת אל התיבה אתה ובניך ואשתך ונשי בניך אתך וכתיב (בראשית ח, טז) צא מן התיבה אתה ואשתך ובניך ונשי בניך אתך וא\"ר יוחנן מיכן אמרו שנאסרו בתשמיש המטה","ת\"ר שלשה שמשו בתיבה וכולם לקו כלב ועורב וחם כלב נקשר עורב רק חם לקה בעורו","(בראשית ח, ח) וישלח את היונה מאתו לראות הקלו המים א\"ר ירמיה מכאן שדירתן של עופות טהורים עם הצדיקים","(בראשית ח, יא) והנה עלה זית טרף בפיה א\"ר אלעזר אמרה יונה לפני הקב\"ה רבש\"ע יהיו מזונותי מרורים כזית ומסורים בידך ואל יהיו מתוקים כדבש ומסורים ביד בשר ודם מאי משמע דהאי טרף לישנא דמזוני הוא דכתיב (משלי ל, ח) הטריפני לחם חוקי","(בראשית ח, יט) למשפחותיהם יצאו מן התיבה א\"ר יוחנן למשפחותם ולא הם","אמר רב חנא בר ביזנא אמר ליה אליעזר לשם רבא כתיב למשפחותיהם יצאו מן התיבה אתון היכן הויתון א\"ל צער גדול היה לנו בתיבה בריה שדרכה להאכילה ביום האכלנוה ביום שדרכה להאכילה בלילה האכלנוה בלילה האי זקיתא לא הוה ידע אבא מה אכלה יומא חד הוה יתיב וקא פאלי רמונא נפל תולעתא מינה אכלה מיכן ואילך הוה גביל לה חיזרא כי מתלע אכלה","אריא אישתא זינתיה דאמר רב לא בציר משיתא ולא טפי מתריסר זינא אישתא אורשינה אשכחיניה אבא דגני בספנא דתיבותא א\"ל לא בעית מזוני א\"ל חזיתיך דהות טרידא אמינא לא אצערך א\"ל יהא רעוא דלא תמות שנאמר (איוב כט, יח) ואומר עם קני אגוע וכחול ארבה ימים","אמר רב חנה בר לואי אמר שם רבא לאליעזר כי אתו עלייכו מלכי מזרח ומערב אתון היכי עבידיתו אמר ליה אייתי הקב\"ה לאברהם ואותביה מימיניה והוה שדינן עפרא והוו חרבי גילי והוי גירי שנאמר (תהלים קי, א) מזמור לדוד נאם ה' לאדוני שב לימיני עד אשית אויביך הדום לרגליך וכתיב (ישעיהו מא, ב) מי העיר ממזרח צדק יקראהו לרגלו יתן לפניו גוים ומלכים ירד יתן כעפר חרבו כקש נדף קשתו","נחום איש גם זו הוה רגיל דכל דהוה סלקא ליה אמר גם זו לטובה יומא חד בעו [ישראל] לשדורי דורון לקיסר אמרי בהדי"],[[0,"א\"כ לא נפנה דרך כרמים","[כלומר לא נסור ולא נפנה את דרך הכרמים] אלא כל שעה נלך בהם כלומר א\"כ לא נלך דרך כבושה ולא נחזור מסורינו אלא נלך ונקלקל השורה דרכים משובשים בקוצים וברקנים כעין שבילי כרמים:"],[1,"לעשתות","כמו עשתונות שיושבין שאנן וחושבין מחשבות רעות:"],[1,"עליתה שמה","אין אש שולט בה:"],[2,"מבין עקבי רגליכם","בשכבת זרע שלכם יכול למחות אתכם ל\"א מבין עקבי רגליכם מן הרגל יוציא ממש מים אם היה רוצה ואי אפשר לכפות רגליכם בעששיות:"],[2,"בשכבת זרע","רותחין ועבין היו עבין ל\"ג ופי' הוא:"],[2,"חמת המלך שככה","נחה מרתחו ה\"נ מים נחו מרותחן:"],[4,"סדרי בראשית","והיינו לשבעת הימים סדר שבעת ימי בראשית שינה להם:"],[4,"זמן קטן אחר זמן גדול","בתחילה אמר להן והיו ימיו מאה ועשרים שנה כשעבר זמן זה ולא שבו לטובה חזר וקבע להם זמן קטן:"],[5,"אישות לבהמה מי אית ליה","נקבה אחת נשכבת לכמה זכרים ואין זו אישות:"],[5,"שלא נעבדה בהן עבירה","שלא נזקקו אלא לבן זוגם:"],[7,"מבליגה","עץ הוא:"],[12,"במותר לי","אפי' באשתי אני אסור:"],[13,"(בני נח","שם וחם ויפת):"],[14,"רק","רוקק זרע מפיו לפיה של נקבה:"],[14,"לקה בעורו","שיצא ממנו כוש:"],[15,"מאתו","גבי עורב לא כתיב מאתו מכאן שדירתם כו' כלומר הנאה הוא שדרים אצלם שמכירים בצדיקים כדאמרי' בדוכתי אחריתא:"],[16,"זית טרף בפיה","בפיה היתה שואלת מזון טרף של זית:"],[17,"למשפחותיהם יצאו מן התיבה","אלמא כל חד וחד בפני עצמו היה ולא היו אוכלין כולם באבוס אחד אלא משפחות [משפחות] היו שרויין:"],[18,"א\"ל אליעזר","[עבד אברהם]:"],[18,"לשם רבא","גדול בנו של נח:"],[18,"היכי הויתון","היאך הייתם יכולין להכין עניניהם בכך לעשות לכל בריה ובריה חפצה:"],[18,"זיקתא","שם בריה:"],[18,"פאלי","מחתך כמו פלי פלויי במסכת נדה (דף כא:):"],[19,"אישתא זינתיה","חמה אחזתו וזנהו ולא היה חושש לדרוס משאר בהמות:"],[19,"לא בציר משיתא ולא טפי מתריסר זיינא אישתא","אין לך חמה קלה שלא תהא חמימותו יכולה לזונו ששת ימים שלא ימות בלא מאכל ואין לך חמה שיכולה לזון יותר מי\"ב ימים בלי מאכל ומשתה כ\"ש ואית דגרסי לא פחות משיתא ירחי ולא טפי מתריסר זנתא אשתא ואארי קאי כלומר לא פחות מששה חדשים ולא יותר מי\"ב חדשים ולא נהירא לי:"],[19,"אורשינא","עוף ושמו חול בלשון המקרא ואינו מת לעולם:"],[19,"בספנא","בחדר ספון ומתוקן לו:"],[20,"[נאום ה' כו'] אליעזר אמר פסוק זה","נאם ה' לאדני אמר הקב\"ה לאברהם שב לימיני אדני וכו':"],[20,"ממזרח זה אברהם","שבא מארם נהרים שהוא במזרח דכתיב (במדבר כג) מן ארם ינחני בלק מלך מואב וגו':"],[21,"כל דהוה סלקא ליה","כל דבר המאורע ליה:"]],[]],[["מאן נשדר נשדר בהדי נחום איש גם זו דמלומד בנסים הוא","כי מטא לההוא דיורא בעא למיבת אמרי ליה מאי איכא בהדך אמר להו קא מובילנא כרגא לקיסר קמו בליליא שרינהו לסיפטיה ושקלו כל דהוה גביה ומלנהו עפרא כי מטא להתם אישתכח עפרא אמר אחוכי קא מחייכי בי יהודאי אפקוהו למקטליה אמר גם זו לטובה אתא אליהו ואידמי להו כחד מינייהו אמר להו דילמא האי עפרא מעפרא דאברהם אבינו הוא דהוה שדי עפרא הוו חרבי גילי הוו גירי בדוק ואשכחו הכי","הוה מחוזא דלא הוו קא יכלי ליה למיכבשיה שדו מההוא עפרא עליה וכבשוה עיילוהו לבי גנזא אמרי שקול דניחא לך מלייה לסיפטא דהבא כי הדר אתא אמרו ליה הנך דיורי מאי אמטית לבי מלכא אמר להו מאי דשקלי מהכא אמטאי להתם שקלי אינהו אמטו להתם קטלינהו להנך דיורי:","דור הפלגה אין להם חלק לעולם הבא וכו': מאי עבוד אמרי דבי רבי שילא נבנה מגדל ונעלה לרקיע ונכה אותו בקרדומות כדי שיזובו מימיו מחכו עלה במערבא א\"כ ליבנו אחד בטורא","(אלא) א\"ר ירמיה בר אלעזר נחלקו לג' כיתות אחת אומרת נעלה ונשב שם ואחת אומרת נעלה ונעבוד עבודת כוכבים ואחת אומרת נעלה ונעשה מלחמה זו שאומרת נעלה ונשב שם הפיצם ה' וזו שאומרת נעלה ונעשה מלחמה נעשו קופים ורוחות ושידים ולילין וזו שאומרת נעלה ונעבוד עבודת כוכבים (בראשית יא, ט) כי שם בלל ה' שפת כל הארץ","תניא רבי נתן אומר כולם לשם עבודת כוכבים נתכוונו כתיב הכא (בראשית יא, ד) נעשה לנו שם וכתיב התם (שמות כג, יג) ושם אלהים אחרים לא תזכירו מה להלן עבודת כוכבים אף כאן עבודת כוכבים","אמר רבי יוחנן מגדל שליש נשרף שליש נבלע שליש קיים אמר רב אויר מגדל משכח אמר רב יוסף בבל ובורסיף סימן רע לתורה מאי בורסיף אמר ר' אסי בור שאפי:","אנשי סדום אין להם חלק לעולם הבא וכו': ת\"ר אנשי סדום אין להן חלק לעולם הבא שנאמר (בראשית יג, יג) ואנשי סדום רעים וחטאים לה' מאד רעים בעוה\"ז וחטאים לעולם הבא","אמר רב יהודה רעים בגופן וחטאים בממונם רעים בגופן דכתיב (בראשית לט, ט) ואיך אעשה הרעה הגדולה הזאת וחטאתי לאלהים וחטאים בממונם דכתיב (דברים טו, ט) והיה בך חטא לה' זו ברכת השם מאד שמתכוונים וחוטאים","במתניתא תנא רעים בממונם וחטאים בגופן רעים בממונם דכתיב (דברים טו, ט) ורעה עינך באחיך האביון וחטאים בגופן דכתיב (בראשית לט, ט) וחטאתי לאלהים לה' זו ברכת השם מאד זו שפיכות דמים שנאמר (מלכים ב כא, טז) גם דם נקי שפך מנשה (בירושלים) הרבה מאד [וגו']","ת\"ר אנשי סדום לא נתגאו אלא בשביל טובה שהשפיע להם הקב\"ה ומה כתיב בהם (איוב כח, ה) ארץ ממנה יצא לחם ותחתיה נהפך כמו אש מקום ספיר אבניה ועפרות זהב לו נתיב לא ידעו עיט ולא שזפתו עין איה לא הדריכוהו בני שחץ לא עדה עליו שחל","אמרו וכי מאחר שארץ ממנה יצא לחם ועפרות זהב לו למה לנו עוברי דרכים שאין באים אלינו אלא לחסרינו [מממוננו] בואו ונשכח תורת רגל מארצנו שנאמר (איוב כח, ד) פרץ נחל מעם גר הנשכחים מני רגל דלו מאנוש נעו","דרש רבא מאי דכתיב (תהלים סב, ד) עד אנה תהותתו על איש תרצחו כולכם כקיר נטוי גדר הדחויה מלמד שהיו נותנין עיניהן בבעלי ממון ומושיבין אותו אצל קיר נטוי ודוחין אותו עליו ובאים ונוטלין את ממונו","דרש רבא מאי דכתיב (איוב כד, טז) חתר בחשך בתים יומם חתמו למו לא (ראו) [ידעו] אור מלמד שהיו נותנים עיניהם בבעלי ממון ומפקידים אצלו אפרסמון ומניחים אותו בבית גנזיהם לערב באים ומריחין אותו ככלב שנא' (תהלים נט, ז) ישובו לערב יהמו ככלב ויסובבו עיר ובאים וחותרים שם ונוטלין אותו ממון","(איוב כד, י) ערום הלכו מבלי לבוש ואין כסות בקרה חמור יתומים ינהגו יחבלו שור אלמנה גבולות ישיגו עדר גזלו וירעו (איוב כא, לב) והוא לקברות יובל ועל גדיש ישקוד","דרש ר' יוסי בציפורי אחתרין ההיא ליליא תלת מאה מחתרתא בציפורי אתו וקא מצערי ליה אמרו ליה יהבית אורחיה לגנבי אמר להו מי הוה ידענא דאתו גנבי כי קא נח נפשיה דרבי יוסי שפעי מרזבי דציפורי דמא","אמרי דאית ליה חד תורא מרעי חד יומא דלית ליה לירעי תרי יומי ההוא יתמא בר ארמלתא הבו ליה תורי למרעיה אזל שקלינהו וקטלינהו אמר להו"],[[0,"בהדי מאן","ביד מי נשלח:"],[1,"כי מטא לההוא דיירא","כשהגיע לאותו מלון:"],[1,"למיבת","ללון:"],[1,"שרינהו לסיטפיה","התירו הארגזים והמרצופין ופתחום ונטלו כל מה שבתוכו:"],[1,"אחוכי","מצחקי:"],[2,"הנך דיורי","אותן בני הכפרים:"],[3,"א\"כ ליבנו אחד בטורא","א\"כ שבנו כדי לעלות לרקיע למה בנו אותו בבקעה היה להם לבנות על אחד ההרים:"],[4,"הפיצם ה'","פיזרם בכל העולם:"],[4,"שדים","יש להם צורת אדם ואוכלין ושותין כבני אדם:"],[4,"רוחין","בלי גוף וצורה:"],[4,"לילין","צורת אדם אלא שיש להם כנפים במסכת נדה (דף נד:):"],[4,"זו שאומרה נעבוד ע\"ז כי שם בלל ה'","בלבל לשונם כדי שלא יהא אחד מכוון לדעת חבירו לעבוד ע\"ז:"],[6,"שליש [נבלע]","נבלעו יסודותיה משוקעת היא בקרקע עד שליש ושליש של מעלה נשרף ושליש אמצעי קיים בקרקע ולא שיהא עומד באויר:"],[6,"אויר מגדל","מראש המגדל (כלומר) [כמו אוירה של עיר] מי שעומד סביב למגדל ורואה אוירה ומראה גובה שלו:"],[6,"משכח","שכן נגזר על אותו מקום שישכח ולכך הם עצמם שכחו את לשונם:"],[6,"בבל ובורסיף סימן רע לתורה","שמשכחין הלמוד מפני שעומדים באויר המגדל:"],[6,"סימן רע","כלומר שמם סימן שכחה היא:"],[6,"למה נקרא שמה בורסיף בור שאפי","בור שנתרוקן מימיו כלומר משכח האדם כל מה שלומד:"],[6,"שאפי","כמו (ב\"מ דף ס.) השופה את היין לשון (ירמיהו מ״ח:י״א) הורק מכלי אל כלי ומפני מה שמה בבל [שמשכחת] אמר רב יוסף כי שם בלל לפי שבלבל הקדוש ברוך הוא את לשונם לשם לכך היא משכחת:"],[8,"רעים בגופם","שטופים בזימה:"],[8,"השמר לך פן יהיה דבר עם לבבך בליעל וגו' והיה בך חטא","והיינו ממון:"],[10,"ארץ ממנה יצא לחם","ארץ שבעה וטובה היא:"],[10,"ותחתיה נהפך כמו אש","ואחר כן נהפכה:"],[11,"וכי מאחר שארץ ממנה יצא לחם","שיש לנו שיפוע לחם למה לנו עוברי דרכים:"],[11,"ונשכח","שלא יעברו עוברי דרכים בארצנו:"],[11,"פרץ","הקב\"ה נחל גפרית ואש:"],[11,"מעם גר","ממקום הליכתו שהיה הולך למעלה והשליכו עליהם הנשכחים מני רגל ונתדלדלו (מאדם) [מארצם] ונעו לדראון:"],[11,"גר","קוררט\"ל בלע\"ז כמו (שמואל ב יד) מים הנגרים:"],[12,"תהותתו","תבקשו תרמיות ותואנות:"],[12,"תרצחו כולכם","ע\"י קיר נטוי וגדר הדחויה:"],[13,"יומם חתמו למו","היום סותמים וסוגרין כאילו לא ידעו אור כלומר סותמין וחותמין:"],[13,"אפרסמון","שלהם להפקידו ביד בעלי ממון כדי שיהו מניחין פקדון שלהם בבית גנזיהם ובלילה מריחין האפרסמון וחותרין שם מנהגו של מפקיד צורר וחותם:"],[15,"דרש ר' יוסי","בי מדרשא חתר בחשך בתים:"],[15,"איחתרו תלת מאה מחתרתא","ע\"י ריח אפרסמון שהיו מריחין ויודעין היכן מניחין ממונם:"],[15,"","מי הוה ידענא דאתו גנבי ל\"א מי הוה ידענא דגנבי אתון:"],[15,"שפעי מרזבי דציפורי דמא","דאדם גדול הוה ואיידי דאמר לעיל איחתרו מחתרתי בציפורי דאתרא דרבי יוסי התם הוה נקיט נמי הא מילתא דכי נח נפשיה כו' לאשמועינן דמצפורי הוה:"],[16,"","דאית ליה תורא. כך היה מנהגם של אנשי סדום מי שהיה לו שור אחד רועה כל בהמות העיר יום א' ומי שאין לו בהמה מגלגלין עליו לרעות ב' ימים:"],[16,"אמר להו","יתמי למרי דתורא דאית ליה חד תורא כו':"]],[]],[["דאית ליה תורא נשקול חד משכא דלית ליה תורא נשקול תרי משכי אמרו ליה מאי האי אמר להו סוף דינא כתחילת דינא מה תחילת דינא דאית ליה תורא מרעי חד יומא דלית ליה תורי מרעי תרי יומי אף סוף דינא דאית ליה חד תורא לשקול חד דלית ליה תורא לשקול תרי","דעבר במברא ניתיב חד זוזא דלא עבר במברא ניתיב תרי דהוה ליה (תורא) [דרא] דלבני אתי כל חד וחד שקל' חדא א\"ל אנא חדא דשקלי דהוה שדי תומי או שמכי אתו כל חד וחד שקיל חדא א\"ל אנא חדא דשקלי","ארבע דייני היו בסדום שקראי ושקרוראי זייפי ומצלי דינא דמחי ליה לאיתתא דחברי' ומפלא ליה אמרי ליה יהבה ניהליה דניעברה ניהליך דפסיק ליה לאודנא דחמרא דחבריה אמרו ליה הבה ניהליה עד דקדחא דפדע ליה לחבריה אמרי ליה הב ליה אגרא דשקל לך דמא","דעבר במברא יהיב ארבעה זוזי דעבר במיא יהיב תמני זוזי זימנא חדא אתא ההוא כובס איקלע להתם אמרו ליה הב ד' זוזי אמר להו אנא במיא עברי אמרו ליה א\"כ הב תמניא דעברת במיא לא יהיב פדיוהו אתא לקמיה דדיינא א\"ל הב ליה אגרא דשקיל לך דמא ותמניא זוזי דעברת במיא","אליעזר עבד אברהם איתרמי התם פדיוהי אתא לקמיה דיינא א\"ל הב ליה אגרא דשקל לך דמא שקל גללא פדיוהי איהו לדיינא אמר מאי האי א\"ל אגרא דנפק לי מינך הב ניהליה להאי וזוזי דידי כדקיימי קיימי","הויא להו פורייתא דהוו מגני עלה אורחין כי מאריך גייזי ליה כי גוץ מתחין ליה אליעזר עבד אברהם אקלע להתם אמרו ליה קום גני אפוריא אמר להון נדרא נדרי מן יומא דמיתת אמא לא גנינא אפוריא","כי הוה מתרמי להו עניא יהבו ליה כל חד וחד דינרא וכתיב שמיה עליה וריפתא לא הוו ממטי ליה כי הוה מית אתי כל חד וחד שקיל דידיה","הכי אתני בינייהו כל מאן דמזמין גברא לבי הילולא לשלח גלימא הוי האי הילולא אקלע אליעזר להתם ולא יהבו ליה נהמא כי בעי למסעד אתא אליעזר ויתיב לסיפא דכולהו אמרו ליה מאן אזמנך להכא א\"ל לההוא [דיתיב] אתה זמנתן [אמר דילמא שמעי בי דאנא אזמינתיה ומשלחי ליה מאניה דהאי גברא] שקל גלימיה ההוא דיתיב גביה ורהט לברא וכן עבד לכולהו עד דנפקי כולהו ואכלא איהו לסעודתא","הויא ההיא רביתא דהות קא מפקא ריפתא לעניא בחצבא איגלאי מלתא שפיוה דובשא ואוקמוה על איגר שורא אתא זיבורי ואכלוה והיינו דכתיב (בראשית יח, כ) ויאמר ה' זעקת סדום ועמורה כי רבה ואמר רב יהודה אמר רב על עיסקי ריבה:","מרגלים אין להם חלק לעולם הבא שנאמר (במדבר יד, לז) וימותו האנשים מוציאי דבת הארץ רעה במגפה וימותו בעולם הזה במגפה לעולם הבא:","עדת קרח אין להם חלק לעולם הבא שנאמר (במדבר טז, לג) ותכס עליהם הארץ בעולם הזה ויאבדו מתוך הקהל לעולם הבא דברי ר\"ע רבי אליעזר אומר עליהם אמר הכתוב (שמואל א ב, ו) ה' ממית ומחיה מוריד שאול ויעל:","ת\"ר עדת קרח אין להם חלק לעולם הבא שנאמר ותכס עליהם הארץ בעולם הזה ויאבדו מתוך הקהל לעולם הבא דברי רבי עקיבא רבי יהודה בן בתירא אומר הרי הן כאבידה המתבקשת שנאמר (תהלים קיט, קעו) תעיתי כשה אובד בקש עבדך כי מצותיך לא שכחתי:","ויקח [קרח] אמר ריש לקיש שלקח מקח רע לעצמו קרח שנעשה קרחה בישראל בן יצהר בן שהרתיח עליו את כל העולם כצהרים בן קהת בן שהקהה שיני מולידיו בן לוי בן שנעשה לויה בגיהנם","וליחשוב נמי בן יעקב בן שעקב עצמו לגיהנם אמר רב שמואל בר רב יצחק יעקב ביקש רחמים על עצמו שנאמר (בראשית מט, ו) בסודם אל תבא נפשי ובקהלם אל תחד כבודי בסודם אל תבא נפשי אלו מרגלים ובקהלם אל תחד כבודי זה עדת קרח","דתן שעבר על דת אל אבירם שאיבר עצמו מעשות תשובה ואון שישב באנינות פלת שנעשו לו פלאות בן ראובן בן שראה והבין","אמר רב און בן פלת אשתו הצילתו אמרה ליה מאי נפקא לך מינה אי מר רבה אנת תלמידא ואי מר רבה אנת תלמידא אמר לה מאי אעביד הואי בעצה ואשתבעי לי בהדייהו אמרה ליה ידענא דכולה כנישתא קדישתא נינהו דכתיב (במדבר טז, ג) כי כל העדה כולם קדושים אמרה ליה תוב דאנא מצילנא לך אשקיתיה חמרא וארויתיה ואגניתיה גואי אותבה על בבא"],[[1,"דעבר במברא","שהמעברות שלהם מימיו עזין והיו דנין כך:"],[1,"דלא עבר במברא","אלא בא דרך אחר:"],[1,"דה\"ל דרא דלבני","מי שהיו לו שורת לבנים ומגבל ועושה אותן היה בא כל חד וחד ונוטל אחת:"],[1,"שדי תומי או שמכי","מי שהיה מפזר ושוטח לפניו שומים או בצלים ליבשן כל א' וא' היה נוטל אחת:"],[1,"אומר לו","לנגזל מה חסרתי לך לא לקחתי ממך אלא שום אחד ונמצא קרח מכאן ומכאן:"],[2,"זייפא","ומצלי דין:"],[2,"יהבה ניהליה","וישכב עמה עד שתהיה מעוברת:"],[2,"עד דקדחא","עד שתצמח אזנו:"],[2,"דפדע","עשה לו פצע כמו פדעת במסכת ע\"ז (דף כח.) כפרדור\"א בלע\"ז:"],[3,"דעבר במיא","עובר ברגליו במים:"],[4,"גללא","מקל ל\"א אבן:"],[4,"א\"ל","דיינא לאליעזר מאי האי:"],[4,"א\"ל","אליעזר אגרא דמחייבת לי דשקלי לך דמא הב ליה לההוא גברא דשקל לי דמא וזוזי דידי כדקיימי קיימי ל\"א ה\"ג ולואי כדקאי קאי כך אמר ליה דיין מי יתן שהייתי כבתחילה:"],[5,"כי אריך גייצו ליה","כשהאורח ארוך יותר מן המטה מקצרין אותו בסכין גייצי לשון גוץ כן שמעתי ואית דגרסי גיידי ליה:"],[5,"ומתחין ליה","עד דמתפרקי אבריו:"],[6,"וכתיב שמיה עילויה","כדי שיכיר כל אחד וא' דינר שלו ויחזור ויטלנו:"],[6,"ורפתא לא ממטו ליה","התנו ביניהם שלא יתנו לו פת כדי שימות ברעב וכשמת אזיל כל חד וחד ושקיל לדינרא דידיה:"],[7,"הכי אתנו בהדייהו כל מאן דמזמן","אכסניא לבי הלולא:"],[7,"לשלחו לגלימיה","יפשיטו את בגדי אותו האיש שהזמינו:"],[7,"ואתא אליעזר","עבד אברהם:"],[7,"ויתיב אסיפא דכולהו","הלך וישב בסוף כולם:"],[7,"א\"ל מאן אזמנך","להכא:"],[7,"א\"ל","אליעזר למאן דיתיב גביה את זמנתני להכא:"],[7,"שקל גלימיה","דיתיב לגביה ורהט לברא שהיה מתיירא שלא ישמעו אנשי המקום שאליעזר אמר שהוא זימנו ולישלחו למאניה הלך וישב לו אצל השני ואמר כמו כן וכן לכל אחד ואחד עד דאזלי כולהו ואכל אליעזר כל הסעודה:"],[8,"רביתא","נערה:"],[8,"בחצבא","בתוך כד שלה כשיוצאת לשאוב מים:"],[8,"שפיוה","סכו אותה:"],[8,"איגר שורא","על גג החומה:"],[8,"כי רבה","על עסקי ריבה:"],[11,"רבי יהודה בן בתירא אומר ויאבדו הרי הן כאבידה המתבקשת","ובאין לעולם הבא שכך אמר דוד על בני קרח תעיתי כשה אובד בקש עבדך הם תעו כשה אובד ואתה ברחמיך הרבים בקש עבדך ותביאם לעוה\"ב:"],[11,"מצותיך לא שכחתי","שקיימו כל מצותיך כדכתיב (במדבר ט״ז:ג׳) כי כל העדה כולם קדושים:"],[12,"מקח רע","התחיל בקטטה:"],[12,"שעשה קרחה בישראל","שנבלעו:"],[12,"שהרתיח","שהכעיס:"],[12,"הקהה שיני מולידיו","שנתביישו אבותיו במעשיו הרעים:"],[13,"בקש רחמים על עצמו","שלא יהא נמנה עמהם:"],[13,"אלו מרגלים","דלא כתיב בהן פלוני בן יעקב:"],[14,"שאיבר לבבו","חזק לבבו כמו (ישעיהו מו) אבירי לב:"],[14,"שישב באנינות","שעשה תשובה על שהיה עמהם תחילה בעצה:"],[14,"נעשו לו פלאות","(שפירש) [שניצל] מהם:"],[14,"ראה והבין","שאין מנהגן כשורה ופירש מהם:"],[15,"אי מר רבה","אם ינצח משה מכל מקום אתה תלמיד ואם קרח מנצח אתה תלמיד מה לך בשררה זו:"],[15,"הואי בעצה","אני הייתי עמהן בעצה ונשבעתי להם שאם יקראוני אלך עמהם:"],[15,"דכולה כנישתא קדישין","כולם צנועים וקדושים ולא יכנסו אלי אם אני פרועה:"]],[]],[["וסתרתה למזיה כל דאתא חזיה הדר אדהכי והכי אבלעו להו","איתתיה דקרח אמרה ליה חזי מאי קעביד משה איהו הוה מלכא לאחוה שוויה כהנא רבא לבני אחוהי שוינהו סגני דכהנא אי אתיא תרומה אמר תיהוי לכהן אי אתו מעשר דשקילתו אתון אמר הבו חד מי' לכהן ועוד דגייז ליה למזייכו ומיטלל לכו כי כופתא עינא יהב במזייכו אמר לה הא איהו נמי קא עביד אמרה ליה כיון דכולהו רבותא דידיה אמר איהו נמי (שופטים טז, ל) תמות נפשי עם פלשתים","ועוד דקאמר לכו עבדיתו תכלתא אי ס\"ד תכלתא חשיבא [מצוה] אפיק גלימי דתכלתא וכסינהו לכולהו מתיבתך היינו דכתיב (משלי יד, א) חכמות נשים בנתה ביתה זו אשתו של און בן פלת ואולת בידה תהרסנה זו אשתו של קרח","(במדבר טז, ב) ויקומו לפני משה ואנשים מבני ישראל חמשים ומאתים מיוחדים שבעדה קריאי מועד שהיו יודעים לעבר שנים ולקבוע חדשים אנשי שם שהיה להם שם בכל העולם","(במדבר טז, ד) וישמע משה ויפול על פניו מה שמועה שמע אמר רבי שמואל בר נחמני א\"ר יונתן שחשדוהו מאשת איש שנאמר (תהלים קו, טז) ויקנאו למשה במחנה א\"ר שמואל בר יצחק מלמד שכל אחד ואחד קנא את אשתו ממשה שנאמר (שמות לג, ז) ומשה יקח את האהל ונטה לו מחוץ למחנה","(במדבר טז, כה) ויקם משה וילך אל דתן ואבירם אמר ר\"ל מכאן שאין מחזיקין במחלוקת דאמר רב כל המחזיק במחלוקת עובר בלאו שנאמר (במדבר יז, ה) ולא יהיה כקרח וכעדתו","רב אשי אמר ראוי ליצטרע כתיב הכא ביד משה לו וכתיב התם (שמות ד, ו) ויאמר ה' לו עוד הבא נא ידך בחיקך","אמר ר' יוסי כל החולק על מלכות בית דוד ראוי להכישו נחש כתיב הכא (מלכים א א, ט) ויזבח אדוניהו צאן ובקר ומריא עם אבן הזוחלת וכתיב התם (דברים לב, כד) עם חמת זוחלי עפר","אמר רב חסדא כל החולק על רבו כחולק על השכינה שנאמר (במדבר כו, ט) בהצותם על ה' א\"ר חמא ברבי חנינא כל העושה מריבה עם רבו כעושה עם שכינה שנאמר (במדבר כ, יג) המה מי מריבה אשר רבו בני ישראל (על) [את] ה'","א\"ר חנינא בר פפא כל המתרעם על רבו כאילו מתרעם על השכינה שנאמר (שמות טז, ח) לא עלינו תלונותיכם כי (אם) על ה' א\"ר אבהו כל המהרהר אחר רבו כאילו מהרהר אחר שכינה שנאמר (במדבר כא, ה) וידבר העם באלהים ובמשה","(קהלת ה, יב) עושר שמור לבעליו לרעתו אמר ר\"ל זה עושרו של קרח (דברים יא, ו) ואת כל היקום אשר ברגליהם א\"ר אלעזר זה ממונו של אדם שמעמידו על רגליו ואמר רבי לוי משוי ג' מאות פרדות לבנות היו מפתחות של בית גנזיו של קרח וכולהו אקלידי וקילפי דגילדא","א\"ר חמא ברבי חנינא ג' מטמוניות הטמין יוסף במצרים אחת נתגלתה לקרח ואחת נתגלתה לאנטונינוס בן אסוירוס ואחת גנוזה לצדיקים לעתיד לבא","וא\"ר יוחנן קרח לא מן הבלועים ולא מן השרופין לא מן הבלועין דכתיב (במדבר טז, לב) ואת כל האדם אשר לקרח ולא קרח ולא מן השרופים דכתיב (במדבר כו, י) באכול האש את חמשים ומאתים איש ולא קרח","במתניתא תנא קרח מן השרופין ומן הבלועין מן הבלועים דכתיב (במדבר כו, י) ותבלע אותם ואת קרח מן השרופין דכתיב (במדבר טז, לה) (ותצא אש מלפני ה') [ואש יצאה מאת ה'] ותאכל את חמשים ומאתים איש וקרח בהדייהו","אמר רבא מאי דכתיב (חבקוק ג, יא) שמש ירח עמד זבולה לאור חציך יהלכו מלמד שעלו שמש וירח לזבול אמרו לפניו רבש\"ע אם אתה עושה דין לבן עמרם נצא ואם לאו לא נצא עד שזרק בהם חצים אמר להן בכבודי לא מחיתם בכבוד בשר ודם מחיתם והאידנא לא נפקי עד דמחו להו","דרש רבא מאי דכתיב (במדבר טז, ל) ואם בריאה יברא ה' ופצתה האדמה את פיה אמר משה לפני הקב\"ה אם בריאה גיהנם מוטב ואם לאו יברא ה' למאי אילימא למבריה ממש והא (קהלת א, ט) אין כל חדש תחת השמש אלא לקרובי פיתחא","(במדבר כו, יא) ובני קרח לא מתו תנא משום רבינו אמרו מקום נתבצר להם בגיהנם וישבו עליו ואמרו שירה אמר רבה בר בר חנה זימנא חדא הוה קאזלינא באורחא אמר לי ההוא טייעא תא ואחוי לך בלועי דקרח אזיל חזא תרי בזעי דהוה קא נפק קיטרא מנייהו שקל גבבא דעמרא אמשיי' מיא ואותביה בריש רומחיה ואחלפי' התם איחרך א\"ל אצית מה שמעת ושמעית דהוו קאמרי הכי משה ותורתו אמת והן בדאים"],[[0,"סתרה למזיה","שערה וישבה על פתח הבית כל מי שהיה בא לקרוא רואה ראשה פרוע וחוזר:"],[1,"מעשר","ראשון דשקליתו אתון אמר הבו חד מי' לכהן:"],[1,"דגייז למזייכו","דכתיב (במדבר ח׳:ז׳) והעבירו תער על [כל] בשרם ומשחק בכם כאילו אתם שוטים:"],[1,"ככופתא","רעי כמו בטולא דכופתא דאמרן לעיל (סנהדרין דף צח:) כגלל הזה אתם חשובים בעיניו:"],[1,"עינא יהב","עין נתן בשעריכם כדי שלא יהא בכם צורה כמותו:"],[1,"אמר לה","קרח איהו נמי משה עצמו גלח כל שערו:"],[1,"כיון דכולא רבותא דידיה הוא","אינו חושש אם גילח עצמו דקאמר לנפשיה תמות נפשי עם פלשתים אגזוז שערי כמותם ומה לי בכך שהם מקיימין אפילו מה שאני מצוה לשחוק אגזוז עכשיו כמותם כדי להפיס דעתם:"],[2,"ועוד דקאמר לכו","עשו פתיל תכלת בד' כנפות הבגד ואי ס\"ד תכלת חשוב מפני מה לא יאמר לעשות כל הבגד כולו תכלת:"],[2,"אפיק גלימא דתכלתא","קח לך בגדים של תכלת וכסינהו לכולהו מתיבתך וכסה בהן בבה\"מ אתה וחברותך:"],[4,"קנא לאשתו","אל (הסתר) [תסתדי] עם משה. קנוי היינו התראה:"],[4,"ונטה לו מחוץ למחנה","יצא מחוץ למחנה שלא יחשדוהו עוד:"],[5,"מכאן שאין מחזיקין במחלוקת","שמחל על כבודו והוא עצמו הלך לבטל מחלוקת:"],[8,"חולק על רבו","חולק על ישיבתו:"],[8,"אשר הצו על משה ועל אהרן בעדת קרח בהצותם על ה'","מעלה עליהם הכתוב כאלו היו חולקים כלפי שכינה:"],[8,"מריבה","תגר וקטטה לפטפט נגדו בדברים:"],[9,"מתרעם","אומר על רבו שנוהג לו מדה כבושה ומדת אכזרית:"],[9,"מהרהר","מחפה עליו דברים:"],[10,"אקלידי","מפתחות:"],[10,"וקולפי","מנעולים:"],[10,"דגילדי","כולם המפתחות והמנעולים של עור היו ואעפ\"כ היו שלש מאות פרדות טעונות ל\"א דגלדא לצורך שקים והמרצופין וכיסין של עור היו:"],[12,"לא מן הבלועין ולא מן השרופין","אלא במגפה מת:"],[12,"ולא קרח","ר\"נ היו לבד קרח דכתיב חמשים ומאתים מחתות ואתה ואהרן איש מחתתו:"],[13,"מן הבלועים ומן השרופין היה","שנשרפה נשמתו וגוף קיים ואח\"כ נתגלגל עד מקום הבלועין ונבלע דכתיב בפרשת פנחס ותבלע אותם ואת קרח עמהם ורבי יוחנן דאמר לא מן הבלועין ולא מן השרופין דריש ליה להאי ואת קרח לאחריו ואת קרח במות העדה במגפה:"],[13,"וקרח בהדייהו","מדכתיב ותאכל את החמשים ומאתים איש מקריבי הקטרת וקרח ממקריבי הקטרת הוה דכתיב חמשים ומאתים מחתות ואתה ואהרן איש מחתתו א\"נ ואת לרבות קרח עמהם:"],[14,"שמש ירח עמד זבולה","לעיל מיניה כתיב ותבקע ארץ בשעת בקיעת הארץ שנבלעו בקרקע שמש וירח עלו לאותו רקיע ששמו זבול ואמרו להקב\"ה אם אי אתה עושה דין לבן עמרם מקרח ועדתו:"],[14,"לא נצא","ונאיר לעולם:"],[14,"בכבודי לא מחיתם","שהרי בכל יום מלכי מזרח ומערב בשעה שמניחין כתריהן בראשם משתחוים לחמה:"],[14,"והאידנא לא נפקי עד דמחו להו","שכך גזר עליהם המקום כן שמעתי ל\"א והאידנא לא נפקי מאחר שראו שהקפיד הקב\"ה על שלא מיחה לכבודו עד דמחו להו לא נפקי שחשו לכבוד המקום על בני אדם שמשתחוים לשמש וירח:"],[15,"אין כל חדש תחת השמש","ואי גיהנם לא אברי עד ההוא שעתא הוה ליה חדש:"],[15,"לקרובי פתחה","שיקרב פתחה של גיהנם ותפתח הארץ במקום שהן:"],[16,"נתבצר","מלשון (ישעיהו כ״ז:י׳) עיר בצורה התקין להון הקב\"ה מקום גבוה שלא העמיקו כל כך בגיהנם ולא מתו:"],[16,"טייעא","סוחר ישמעאל:"],[16,"בלועי","מקום שנתבלעו לשם עדת קרח:"],[16,"בזעא","ראה נקב שממנו יצא עשן:"],[16,"גבבא","גיזה:"],[16,"אמשיה","שרה אות' במים לשון (ברכות דף יד:) משי ידיה:"],[16,"","(וכל שלשים יום. חוזר לגיהנם ועולה לשם):"]],[]],[["א\"ל כל תלתין יומין מהדרא להו גיהנם כבשר בתוך קלחת ואמרי הכי משה ותורתו אמת והן בדאים:","דור המדבר אין להם חלק לעולם הבא וכו': ת\"ר דור המדבר אין להם חלק לעולם הבא שנאמר (במדבר יד, לה) במדבר הזה יתמו ושם ימותו יתמו בעולם הזה ושם ימותו בעולם הבא ואמר (תהלים צה, יא) אשר נשבעתי באפי אם יבואון אל מנוחתי דברי ר\"ע","ר\"א אומר (הן באין) לעולם הבא שנאמר (תהלים נ, ה) אספו לי חסידי כורתי בריתי עלי זבח אלא מה אני מקיים אשר נשבעתי באפי באפי נשבעתי וחוזרני בי","רבי יהושע בן קרחה אומר לא נאמר פסוק זה אלא כנגד דורות הבאים אספו לי חסידי אלו צדיקים שבכל דור ודור כורתי בריתי (עלי זבח) אלו חנניה מישאל ועזריה שמסרו עצמן לתוך כבש האש עלי זבח [אלו] ר\"ע וחביריו שמסרו עצמן לשחיטה על דברי תורה","ר\"ש בן מנסיא אומר באים הן לעולם הבא שנא' (ישעיהו לה, י) ופדויי ה' ישובון ובאו ציון ברנה אמר רבה בר בר חנה א\"ר יוחנן שבקה ר\"ע לחסידותיה שנאמר (ירמיהו ב, ב) הלוך וקראת באזני ירושלים לאמר זכרתי לך חסד נעוריך אהבת כלולותיך לכתך אחרי במדבר בארץ לא זרועה ומה אחרים באים בזכותם הם עצמן לא כל שכן:","\u0001מתני׳\u0002 עשרת השבטים אינן עתידין לחזור שנא' (דברים כט, כז) וישליכם אל ארץ אחרת כיום הזה מה היום הולך ואינו חוזר אף הם הולכים ואינן חוזרים דברי ר\"ע ר\"א אומר כיום הזה מה יום מאפיל ומאיר אף עשרת השבטים שאפילה להן כך עתידה להאיר להם:","\u0001גמ׳\u0002 ת\"ר עשרת השבטים אין להם חלק לעוה\"ב שנאמר (דברים כט, כז) ויתשם ה' מעל אדמתם באף ובחמה ובקצף גדול ויתשם ה' מעל אדמתם בעוה\"ז וישליכם אל ארץ אחרת לעוה\"ב דברי ר\"ע ר\"ש בן יהודה איש כפר עכו אומר משום ר\"ש אם מעשיהם כיום הזה אינן חוזרין ואם לאו חוזרין","רבי אומר באים הם לעוה\"ב שנאמר (ישעיהו כז, יג) ביום ההוא יתקע בשופר גדול וגו' אמר רבה בר בר חנה א\"ר יוחנן שבקה ר\"ע לחסידותיה שנא' (ירמיהו ג, יב) הלוך וקראת את הדברים האלה צפונה ואמרת שובה משובה ישראל נאם ה' ולא אפיל פני בכם כי חסיד אני נאם ה' לא אטור לעולם","מאי חסידותיה דתניא קטני בני רשעי ישראל אין באין לעוה\"ב שנא' (מלאכי ג, יט) כי הנה היום בא בוער כתנור והיה כל זדים וכל עושי רשעה קש ולהט אותם היום הבא אמר ה' צבאות אשר לא יעזוב להם שורש וענף שורש בעוה\"ז וענף לעוה\"ב דברי רבן גמליאל","ר\"ע אומר באים הם לעוה\"ב שנא' (תהלים קטז, ו) שומר פתאים ה' שכן קורין בכרכי הים לינוקא פתיא ואומר (דניאל ד, כ) גודו אילנא וחבלוהי ברם עיקר שרשוהי בארעא שבוקו ואלא מה אני מקיים לא יעזוב להם שורש וענף שלא יניח להם לא מצוה ולא שיורי מצוה ד\"א שורש זו נשמה וענף זה הגוף","אבל קטני בני רשעי עובדי כוכבים ד\"ה אין באין לעוה\"ב ור\"ג נפקא ליה (ישעיהו כו, יד) מותאבד כל זכר למו","אתמר קטן מאימתי בא לעוה\"ב ר' חייא ור\"ש בר ר' חד אמר משעה שנולד וחד אמר משעה שסיפר מ\"ד משעה שנולד שנא' (תהלים כב, לב) יבואו ויגידו צדקתו לעם נולד כי עשה ומ\"ד משעה שסיפר דכתיב (תהלים כב, לא) זרע יעבדנו יסופר לה' לדור","אתמר רבינא אמר משעה שנזרע דכתיב זרע יעבדנו ר\"נ בר יצחק אמר משעה שנימול דכתיב (תהלים פח, טז) עני אני וגוע מנוער נשאתי אימיך אפונה","תנא משום ר\"מ משעה שיאמר אמן שנא' (ישעיהו כו, ב) פתחו שערים ויבא גוי צדיק שומר אמוני' אל תקרי שומר אמונים אלא שאומר אמן"],[[0,"אמר ליה","ההוא טייעא:"],[0,"כל תלתין יומין מהדר להו גיהנם","הכא:"],[0,"ואמרי הכי משה ותורתו אמת","שנסה כמה פעמים וראה שכל שלשים יום עשן יוצא משם ושומע שאומרין משה ותורתו אמת וכו':"],[1,"באפי","לא גרסינן:"],[1,"שנאמר","לעיל מיניה קרא ארבעים שנה אקוט בדור דהיינו דור המדבר:"],[2,"כורתי בריתי עלי זבח","והיינו דור המדבר שכרתו ברית של מקום עלי זבחים ושלמים דכתיב (שמות כד ה) ויזבחו זבחים שלמים, וכתיב (שמות כד ח) ויזרוק על העם ויאמר הנה דם הברית אשר כרת ה' עמכם:"],[2,"נשבעתי וחוזרני בי","והיינו אשר נשבעתי באפי מפני כעסי נשבעתי ומתחרט אני:"],[3,"אלו חנניה מישאל ועזריה","שמסרו עצמן למיתה בשביל בריתו של מקום:"],[4,"ופדויי ה'","אלו דור המדבר שנפדו ממצרים:"],[4,"שבקיה ר' עקיבא לחסידותיה","שרגיל לזכות את ישראל והשתא מחייב להו דאמר לעיל (סנהדרין דף קח.) דור המדבר אין להם חלק לעולם הבא ולקמן מפרש מאי חסידותיה:"],[4,"שנאמר הלוך וקראת","כלומר שהרי היה יכול לדרוש שיש להם חלק [לעולם הבא] דכתיב הלוך וקראת וגו':"],[5,"מתני' עשרת השבטים","שהגלה סנחריב שנאמר (מלכים ב יח יא) וינחם בחלח ובחבור נהר גוזן וערי מדי:"],[5,"אין עתידים לחזור","ממקום שגלו והא דאמרינן בגמרא דירמיה החזירן לא שהחזירן כולן אלא מקצתם החזיר:"],[5,"שנאמר וישליכם אל ארץ אחרת כיום הזה","שכך גזר להם הקב\"ה שכיון שעוזבין את תורתו הוא מגלה אותן:"],[5,"כיום הזה מה היום מאפיל","בבוקר אפל ובצהרים מאיר אי נמי בערב אפל והולך ולמחרתו מאיר אף עשרת השבטים (אין) עתידין לחזור להיות להם חלק לעולם הבא לא בבניהם ובני בניהם קאמר אלא אותן שגלו עצמן אין להם חלק שרשעים גמורין הם אבל בניהם ודורות הבאים זוכין ומזכין. מ\"ר:"],[5,"","וישליכם — משמע שיהו כולם גולין במקום אחד אל ארץ אחרת והיינו עשרת השבטים שהגלם סנחריב והושיבם במקום אחד כדאמרינן (לעיל סנהדרין צד, א) שהוליכם למדינת אפריקי אבל שני השבטים לא גלו למקום אחד אלא נתפזרו בכל הארצות ועליהם הוא אומר אשרקה להם ואקבצם (זכריה י ח):"],[5,"","הכי גרסינן מתניתין עשרת השבטים אין עתידין לחזור:"],[6,"גמ' תנו רבנן עשרת השבטים אין להם חלק לעולם הבא שנאמר ויתשם ה' מעל אדמתם וגו'","ואית דמפרשי עשרת השבטים אין להם חלק לעולם הבא היינו לימות המשיח שלא יקבלם משיח עם שאר גליות לפי שספרו בגנות ארץ ישראל כדאמרן לעיל (שם.) כי מטו שוש וכו' ובדבר הזה נענשו מרגלים:"],[6,"ר\"ש אומר","מאי כהיום הזה לומר לך אם מעשיהם כהיום הזה לא יהא להם חלק לעולם הבא:"],[6,"ואם [לאו]","שיחזרו בתשובה יחזרו גם הם מגלות ויש להם חלק לעולם הבא:"],[7,"האובדים בארץ אשור","אלו י' השבטים והנדחים בארץ מצרים אלו דור המדבר וכן לשון התוספתא ולא שמעתי עוד:"],[7,"שובה משובה","שכל ישראל עתידין לחזור:"],[8,"קטני בני רשעי ישראל","רשעי ישראל עצמן פשיטא דאין להם חלק לעולם הבא כדאמרינן בפרק בתרא דכתובות (דף קיא:) רפאים בל יקומו מי שמרפה עצמו מדברי תורה אבל בנים שלהם קטנים ולא חטאו פליגי בהו:"],[8,"שורש וענף","אלו בנים קטנים שלהם:"],[8,"שורש בעולם הזה","שימותו נפלים:"],[8,"וענף לעולם הבא","שאף על פי שאבותיהם היו רשעים הם לא חטאו:"],[9,"עיקר שרשוהי בארעא שבוקו","אלו הבנים הקטנים שאף על פי שאבות אין להם חלק תקנה יש להם:"],[9,"שלא יניח","להם הקב\"ה:"],[9,"לא מצוה ולא שיורי מצוה","לא מצוה חמורה ולא מצוה קלה הכל יהא מעביר ומשלם שכרם לאלתר כדי לטרדן מן העולם:"],[9,"זו נשמה","שמעמדת הגוף כשרש שמעמיד האילן:"],[10,"אבל קטני בני רשעי אומות העולם","דוקא קאמר רשעי דאילו חסידי אומות העולם פליגי בה ואיכא למאן דאמר הן עצמן באין ואיכא למאן דאמר אינן באין כדאמרן (סנהדרין קה א) ישובו רשעים לשאולה כל גוים שכחי אלהים מכאן שאין להם חלק אמר לו ר' יהושע וכי נאמר בכל גוים והלא לא נאמר אלא כל גוים שכחי אלהים הא אין שכחי אלהים יש להן חלק [לעוה\"ב]:"],[10,"","הכי גרסינן אבל קטני רשעי אומות העולם דברי הכל אינן באין:"],[10,"מותאבד כל זכר למו נפקא ליה","כלומר לתנא דברייתא והאי דנפקא ליה דברי הכל היא דהא שורש וענף מיבעיא ליה למר כדאית ליה ומר כדאית ליה:"],[11,"זרע יעבדנו יסופר לה' לדור","זרע המסופר יעבדנו לה' לדור ודור שיחזור לו ויחיה:"],[12,"משעה שנזרע","משעה שנקלט הזרע במעי אשה אפילו הפילה אמו ונמחה יש לו חלק לעתיד דכתיב זרע יעבדנו והכי אמר בכתובות בפרק בתרא (דף קיא.) נבלתי יקומון לרבות נפלים:"],[12,"עני אני וגוע מנוער","אף על פי שאני עני גויעתי חשובה גויעה וראוי לומר עלי ויגוע ויאסף כלומר שזוכה אני לעתיד לבא כצדיקים שנאמר בהן גויעה ומאימתי משעה שאני נושא אמיך ופחדך אפונה מתגלגלת ושכונה עלי והיינו מילה שבבשרו שאנו משמרים מאימתו של הקב\"ה:"],[12,"אפונה","לשון אופן:"]],[]],[["מאי אמן א\"ר חנינא אל מלך נאמן","(ישעיהו ה, יד) לכן הרחיבה שאול נפשה ופערה פיה לבלי חוק אמר ר\"ל למי שמשייר אפי' חוק אחד א\"ר יוחנן לא ניחא למרייהו דאמרת להו הכי אלא אפי' לא למד אלא חוק אחד","(שנאמר) (זכריה יג, ח) והיה בכל הארץ נאם ה' פי שנים בה יכרתו ויגועו והשלישית יותר בה אמר ר\"ל שלישי של שם א\"ל רבי יוחנן לא ניחא למרייהו דאמרת להו הכי אלא אפי' שלישי של נח","(ירמיהו ג, יד) כי אנכי בעלתי בכם ולקחתי אתכם אחד מעיר ושנים ממשפחה אמר ר\"ל דברים ככתבן א\"ל ר' יוחנן לא ניחא ליה למרייהו דאמרת להו הכי אלא אחד מעיר מזכה כל העיר כולה ושנים ממשפחה מזכין כל המשפחה כולה יתיב רב כהנא קמיה דרב ויתיב וקאמר דברים ככתבן א\"ל רב לא ניחא ליה למרייהו דאמרת להו הכי אלא אחד מעיר מזכה כל העיר ושנים ממשפחה מזכין כל המשפחה","חזייה דהוה קא חייף רישיה וסליק ויתיב קמיה דרב א\"ל (איוב כח, יג) ולא תמצא בארץ החיים א\"ל מילט קא לייטת לי א\"ל קרא קאמינא לא תמצא תורה במי שמחיה עצמו עליה","תניא רבי סימאי אומר נאמר (שמות ו, ז) ולקחתי אתכם לי לעם ונאמר והבאתי אתכם מקיש יציאתן ממצרים לביאתן לארץ מה ביאתן לארץ שנים מס' ריבוא אף יציאתן ממצרים שנים מס' ריבוא אמר רבא וכן לימות המשיח שנא' (הושע ב, יז) וענתה שמה כימי נעוריה וכיום עלותה מארץ מצרים","תניא אמר ר' אלעזר ברבי יוסי פעם אחת נכנסתי לאלכסנדריא של מצרים מצאתי זקן אחד ואמר לי בא ואראך מה עשו אבותי לאבותיך מהם טבעו בים מהם הרגו בחרב מהם מעכו בבנין ועל דבר זה נענש משה רבינו שנא' (שמות ה, כג) ומאז באתי אל פרעה לדבר בשמך הרע לעם הזה","אמר לו הקב\"ה חבל על דאבדין ולא משתכחין הרי כמה פעמים נגליתי על אברהם יצחק ויעקב באל שדי ולא הרהרו על מדותי ולא אמרו לי מה שמך אמרתי לאברהם (בראשית יג, יז) קום התהלך בארץ לארכה ולרחבה כי לך אתננה בקש מקום לקבור את שרה ולא מצא עד שקנה בד' מאות שקל כסף ולא הרהר על מדותי","אמרתי ליצחק (בראשית כו, ג) גור בארץ הזאת ואהיה עמך ואברכך בקשו עבדיו מים לשתות ולא מצאו עד שעשו מריבה שנאמר (בראשית כו, כ) ויריבו רועי גרר עם רועי יצחק לאמר לנו המים ולא הרהר אחר מדותי","אמרתי ליעקב (בראשית כח, יג) הארץ אשר אתה שוכב עליה לך אתננה ביקש מקום לנטוע אהלו ולא מצא עד שקנה במאה קשיטה ולא הרהר אחר מדותי ולא אמרו לי מה שמך ואתה אמרת לי מה שמך בתחלה ועכשיו אתה אומר לי (שמות ה, כג) והצל לא הצלת את עמך (שמות ו, א) עתה תראה (את) אשר אעשה לפרעה במלחמת פרעה אתה רואה ואי אתה רואה במלחמת שלשים ואחד מלכים","(שמות לד, ח) וימהר משה ויקוד ארצה וישתחו מה ראה משה","ר' חנינא בן גמלא אמר ארך אפים ראה ורבנן אמרי אמת ראה: תניא כמ\"ד ארך אפים ראה דתניא כשעלה משה למרום מצאו להקב\"ה שיושב וכותב ארך אפים אמר לפניו רבונו של עולם ארך אפים לצדיקים אמר לו אף לרשעים א\"ל רשעים יאבדו א\"ל השתא חזית מאי דמבעי לך","כשחטאו ישראל אמר לו לא כך אמרת לי ארך אפים לצדיקים"],[[0,"מאי אמן","כשעונין על כל ברכה וברכה אמן היאך משמע קבלת יראת שמים:"],[0,"אל מלך נאמן","בנוטריקון שמאמין עליו הקב\"ה:"],[1,"למי שמשייר אפילו חק אחד","מלשמרו נידון בגיהנם:"],[1,"לא ניחא ליה למרייהו","אין הקב\"ה רוצה שתהא דן את ישראל כל כך לכף חובה:"],[2,"פי שנים בה יכרתו","ויגועו והשלישית יותר בה:"],[2,"אמר ר\"ל שלישי של שם","שב' חלקים של כל העולם יהיו נכרתים וחלק ג' יותר בה ואיזה חלק שלישי כל שלישיות שיש לשלש אנו משלשין שמנח נפרדו כל העולם וג' בנים היו לו הרי שליש בניו שם ושלישי של שם הוא ארפכשד כדכתיב בני שם עילם ואשור וארפכשד ולוד וארם ומסתמא בזרעו של ארפכשד יהיה שארית הואיל וישראל יוצאים ממנו ושלישי של ארפכשד שהוא שלישי של שם שהוא שלישי של נח יוותר וכל העולם יכרת ולדברי ר\"ל נמצאו ישראל מתמעטין ביותר שמארפכשד יצאו ישראל כדכתיב בפ' נח ארפכשד הוליד את שלח ושלח הוליד את עבר ועבר הוליד את פלג עד אברהם וכשאתה מחלק לג' חלקים זרעו של ארפכשד כגון בני ישראל וישמעאל שהן בני אברהם ובני לוט ובני הרן וכן שאר האומות שיצאו ממנו לג' חלקים שמא ישראל יהיו מרובין וקרובין להיות כנגד כולם ולא יגיעו כל זרע ארפכשד להיות פי שנים אא\"כ ישראל משלימין רובן או חציין ונמצאו ישראל מתמעטין בתוך פי שנים:"],[2,"לא ניחא ליה למרייהו","להקב\"ה שאתה ממעט אותן כל כך אלא אפילו שלישי של נח כלומר מכל בני נח דהיינו מכל העולם כולו יותר השליש ומסתמא אותו חלק הג' שישראל בו יהיה שארית ואם אין ישראל מרובין כל כך להיות אחד מג' שבעולם יהיו הגרים וחסידי עובדי כוכבים להשלים לשליש ואם הם מרובין להיות יותר מחלק השלישית יתמעטו קצת ומ\"מ לרבי יוחנן אין ישראל מתמעטין כל כך כמו לדברי ר\"ש בן לקיש מ\"ר ל\"א שלישי של שם והשלישית משמע שני שליש לכך נאמר שלישית שלישית של שלישי לשם וכתיב ובני שם עילם ואשור וארפכשד וישראל מארפכשד הוו ושלישית מארפכשד שהוא שלישי לשם יותר היינו שלישית מישראל אלא שלישי שלישי של נח כלומר כולו ארפכשד יותר בה שהוא שלישי שלישי של נח דשם היה בן שלישי של נח דכתיב (בראשית י) ובני נח שם חם ויפת וארפכשד שלישי לשם ועיקר:"],[3,"דברים ככתבן","שלא ימלטו אלא אחד מעיר ושנים ממשפחה:"],[3,"ולקחתי אחד מעיר","בשביל חסיד אחד שבעיר אקח את כל העיר כולה:"],[4,"חזייה","רב לרב כהנא:"],[4,"דקא חייף רישיה","חופף ראשו ומעדן בעצמו בשעה שהיה לו ללמוד תורה:"],[4,"לא תמצא בארץ החיים","משמע שמקללו לא תבוא לעוה\"ב:"],[5,"נאמר","בפרשת וארא ולקחתי אתכם לי לעם וכתיב בתריה והבאתי אתכם אל הארץ:"],[5,"מה ביאתם לארץ שנים מס' רבוא","שלא נשתיירו מס' רבוא שיצאו ממצרים אלא ב' אנשים יהושע וכלב כדאמרינן בבבא בתרא בפ' יש נוחלין (בבא בתרא דף קכא.) לא נגזרה גזרה לא בפחות מכ' ולא ביותר מס' שנה בהנך נמי ששים רבוא שנמנו במדבר לא אחשוב לא פחות מבן כ' שנה ויותר מס':"],[5,"אף יציאתן ממצרים שנים מס' רבוא","שמכל ס' רבוא שהיו במצרים לא נשתייר מהם אלא שנים בלבד ואותם שנים של ס' רבוא עלו [לס' רבואות שיצאו אחד מס' רבוא שהיו בהם] והשאר מתו כולם בשלשת ימי אפילה שלא יהיו מצרים רואין במפלתן של ישראל:"],[5,"וכן לימות המשיח","שלא ישארו מכל ס' רבוא אלא ב':"],[5,"וענתה שמה כימי נעוריה וכיום עלותה מארץ מצרים","עניים ושפלים יהיו כימי עלותה מארץ מצרים:"],[6,"מעכו בבנין","היו בונין אותם במקום לבנים:"],[6,"ועל דבר זה נענש משה רבינו","שכשראה שנעשה לישראל כך התחיל להתרעם ולהרהר לפני הקב\"ה אמר משה לפני הקב\"ה ומאז באתי:"],[7,"א\"ל חבל על דאבדין ולא משתכחין","הפסד גדול יש על גדולים שאבדו ואיני יכול למצוא חסידים אחרים כמותם שאין אתה כאברהם ויצחק ויעקב שלא הרהרו אחרי מדותי:"],[7,"אל שדי","שאמרתי לו אני אל שדי פרה ורבה וגו' (בראשית ל״ה:י״א) אני אל שדי התהלך לפני והיה תמים (שם יז) והייתי מבטיחו שכל א\"י לו ולבניו ולא אמרו מה שמך כמו שעשית אתה:"],[9,"לנטוע אהלו","כמו [ויטע] אהלי אפדנו (דניאל י״א:מ״ה) ולשון נטיעה שייך באהל:"],[9,"בתחלה אמרת לי מה שמך","ועכשיו הרהרת על מדותי ואמרת הצל לא הצלת את עמך:"],[9,"עתה תראה","הפעם תראה נפלאות שאני עושה להם:"],[10,"מה ראה","על איזה מדה (אחת) של י\"ג [מדות] ראה והשתחוה:"],[11,"אמת ראה","במדותיו שנקרא אמת ונתיירא אם נתחייבו כלייה אם הוא דן אותן בדין גמור ומיהר והתפלל עליהם שלא יהא דן אותן לפי מעשיהם:"],[11,"ה\"ג תניא כמ\"ד ארך אפים ראה דתניא כשעלה משה למרום וכו' אמר לו רשעים יאבדו","ולא יהיה לך ארך אפים עליהם:"],[12,"אמר לו","הקב\"ה לא כך אמרת ארך אפים לצדיקים ולא לרשעים:"]],[]],[["אמר לפניו רבש\"ע ולא כך אמרת לי אף לרשעים והיינו דכתיב (במדבר יד, יז) ועתה יגדל נא כח ה' כאשר דברת לאמר","ר' חגא הוה סליק ואזיל בדרגא דבי רבה בר שילא שמעיה לההוא ינוקא דאמר (תהלים צג, ה) עדותיך נאמנו מאד לביתך נאוה קדש ה' לאורך ימים וסמיך ליה (תהלים צ, א) תפלה למשה וגו' אמר ש\"מ ארך אפים ראה","א\"ר אלעזר א\"ר חנינא עתיד הקב\"ה להיות עטרה בראש כל צדיק וצדיק שנאמר (ישעיהו כח, ה) ביום ההוא יהיה ה' צבאות לעטרת צבי ולצפירת תפארה לשאר עמו וגו' מאי לעטרת צבי ולצפירת תפארה לעושים רצונו ומצפים לישועתו יכול לכל ת\"ל לשאר עמו למי שמשים עצמו כשירים","(ישעיהו כח, ו) ולרוח משפט ליושב על המשפט ולגבורה משיבי מלחמה שערה ולרוח משפט זה הרודה את יצרו וליושב על המשפט זה הדן דין אמת לאמיתו ולגבורה זה המתגבר ביצרו משיבי מלחמה זה שנושא ונותן במלחמתה של תורה שערה אלו שמשכימין ומעריבין בבתי כנסיות ובתי מדרשות","אמרה מדת הדין לפני הקב\"ה רבש\"ע מה נשתנו אלו מאלו אמר לה (ישעיהו כח, ז) וגם אלה ביין שגו ובשכר תעו [וגו'] פקו פליליה ואין פוקה אלא גיהנם שנאמר (שמואל א כה, לא) לא תהיה זאת לך לפוקה ואין פלילה אלא דיינין שנאמר (שמות כא, כב) ונתן בפלילים:","\u0001מתני׳\u0002 אנשי עיר הנדחת אין להם חלק לעוה\"ב שנאמר (דברים יג, יד) יצאו אנשים בני בליעל מקרבך וידיחו את (אנשי) [יושבי] עירם ואינן נהרגים עד שיהיו מדיחיה מאותה העיר ומאותו השבט ועד שיודח רובה ועד שידיחוה אנשים הדיחוה נשים וקטנים או שהודח מיעוטה או שהיה מדיחיה חוצה לה הרי אלו כיחידים וצריכין ב' עדים והתראה לכל אחד ואחד","זה חומר ביחידים מבמרובים שהיחידים בסקילה לפיכך ממונם פלט והמרובין בסייף לפיכך ממונם אבד","(דברים יג, טז) הכה תכה את יושבי העיר הזאת לפי חרב החמרת והגמלת העוברת ממקום למקום הרי אלו מצילין אותה","שנא' (דברים יג, טז) החרם אותה ואת כל אשר בה ואת בהמתה לפי חרב מכאן אמרו נכסי צדיקים שבתוכה אובדין שבחוצה לה פליטין ושל רשעים בין שבתוכה בין שבחוצה לה הרי אלו אובדין","שנאמר (דברים יג, יז) ואת כל שללה תקבוץ אל תוך רחבה וגו' אם אין לה רחוב עושין לה רחוב היתה רחבה חוצה לה כונסין אותה לתוכה","שנאמר (דברים יג, יז) ושרפת באש את העיר ואת כל שללה כליל לה' אלהיך שללה ולא שלל שמים מכאן אמרו ההקדשות שבה יפדו ותרומות ירקבו מעשר שני וכתבי הקדש יגנזו","כליל לה' אלהיך אמר ר\"ש אמר הקב\"ה אם אתם עושין דין בעיר הנדחת מעלה אני עליכם כאילו אתם מעלים עולה כליל לפני","(דברים יג, יז) והיתה תל עולם לא תעשה גנות ופרדסים דברי ר' יוסי הגלילי ר\"ע אומר לא תבנה עוד לכמות שהיתה אינה נבנית אבל נעשית היא גנות ופרדסים ולא ידבק בידך מאומה מן החרם שכל זמן שהרשעים בעולם חרון אף בעולם אבדו רשעים מן העולם נסתלק חרון אף מן העולם:","\u0001גמ׳\u0002 ת\"ר יצאו הן ולא שלוחין אנשים אין אנשים פחות מב' דבר אחר אנשים ולא נשים אנשים ולא קטנים","בני בליעל בנים שפרקו עול שמים מצואריהם מקרבך ולא מן הספר יושבי עירם ולא יושבי עיר אחרת לאמר שצריכין עדים והתראה לכל אחד ואחד","איתמר ר' יוחנן אמר חולקין עיר אחת לשני שבטים ור\"ל אמר אין חולקין עיר אחת לב' שבטים איתיביה ר' יוחנן לר\"ל עד שיהו מדיחיה מאותה העיר ומאותו שבט מאי לאו אע\"ג דמדיחיה מאותה העיר אי איכא מאותו שבט אין אי לא לא ש\"מ חולקין עיר אחת לב' שבטים","לא דנפלה ליה בירושה א\"נ דיהבוה ניהליה במתנה","איתיביה (יהושע כא, טז) ערים תשע מאת שני השבטים האלה מאי לאו ארבע ופלגא מהאי וארבע ופלגא מהאי וש\"מ חולקין עיר אחת לב' שבטים לא ארבעה מהאי וחמש מהאי","אי הכי לפרוש פרושי"],[[0,"אמר לפניו וכו'","והשתא [מסתברא] כמ\"ד ארך אפים ראה שכיון שראה [מדה זו] בהקב\"ה שהוא ארך אפים אף לרשעים שמח:"],[1,"עדותיך וגו' ה' לאורך ימים","היינו מדת ארך אפים ועליה אמר משה עדותיך נאמנו מאד שראה אותו בחורב ופסוק זה מרע\"ה אמרו דכתיב לעיל מיניה תפלה למשה איש האלהים וגו':"],[2,"יכול לכל","למי שעושין צביונו אע\"פ שמתגאה:"],[2,"כשירים","שיריים שאין נחשבין כך אינו חשוב בעיניו ואינו מתגאה:"],[3,"ולרוח משפט","שופט את רוחו:"],[3,"שרודה ביצרו","שבועט ביצרו וחוזר בתשובה מן העבירה שעבר:"],[3,"ומתגבר ביצרו","מרגיז יצ\"ט על יצה\"ר אם היצה\"ר אמר לו עשה עבירה זו לא דיו שנמנע מן העבירה אלא הולך ועושה מצוה ומתגבר עדיף מרודה:"],[3,"שערה","אלו בתי כנסיות:"],[4,"מה נשתנו אלו מאלו","שיש בהם מדות הללו מן השאר אמר הקב\"ה ביין שגו:"],[4,"","ואין פלילה אלא דיינין:"],[5,"מתני' יצאו אנשים בני בליעל מקרבך","שאין להם חלק לעוה\"ב:"],[5,"וידיחו את (אנשי) [יושבי] עירם","הא אין נהרגים עד שיהיו מדיחיה מאותה העיר ואותו השבט עצמה דכתיב מקרבך מקרב אותו שבט עצמו:"],[5,"עד שיודח רובה","דכתיב ויושבי העיר משמע ישובה של עיר היינו רובה לישנא אחרינא עד שיודח רובה דכתיב מקרבך קרי ביה מרובך:"],[5,"","ה\"ג עד שיודח רובה עד שידיחוה אנשים:"],[5,"או שהיו מדיחיה חוצה לה","שלא היו מאותה העיר:"],[5,"הרי אלו כיחידים","שהן בסקילה וממונן פלט:"],[5,"וצריכים ב' עדים והתראה לכל אחד","כדיליף בגמרא יחידים בסקילה לפיכך ממונן פלט ומתוך שהחמרת עליו במיתתו הקלת עליו בממונו:"],[7,"הכה תכה את יושבי העיר ההיא לפי חרב החמרת והגמלת העוברת ממקום למקום מצילין","מדכתיב יושבי מכלל דשיירה של חמרים וגמלים שנשתהו בעיר ל' יום כדמפרש בגמרא דהוו להו יושבי העיר הרי אלו מצילין אם רוב אנשי העיר הודחו וחמרים וגמלים משלימין המיעוט ועושה אותם רוב מצילין עליהם שאין ממונם אבד אלא נדונים כיחידים וגורמין נמי לעשות אותה עיר הנדחת אם משלימים לעיר הנדחת לעשות רוב אלא הא פסיקא טפי דחמרת וגמלת אין דעתם מעורבת עם בני העיר להיות נדונין עמהן:"],[8,"ה\"ג החרם אותה וכל אשר בה מכאן אמרו צדיקים וכו' ושל רשעים בין מתוכה בין מחוצה לה אבודים","בגמרא מפרש לה מדכתיב כל:"],[9,"ואת כל שללה תקבוץ אל תוך רחובה אין לה רחוב עושין לה רחוב","ורחובה דהשתא נמי משמע:"],[9,"היה רחובה חוצה לה","שמקום קבוץ בני העיר היה חוץ לעיר כונסין אותה לעיר שצריך לעשות לה רחוב בתוכה רחוב סרטיא גדולה:"],[10,"את העיר ואת כל שללה ולא שלל שמים","דשלל שמים פלט:"],[10,"מכאן אמרו הקדשות שבתוכה יפדו","כלומר אין נשרפין אלא הרי הם כשאר הקדש שצריך פדייה כ\"ש דשלל שמים הם:"],[10,"ותרומות ירקבו","ובגמ' מוקמי לה בתרומה ביד כהן דממון כהן הוא וחל עליה איסור דעיר הנדחת דנהי דבשריפה לא הויא עם שאר שללה דקדש אקרי ולא מזלזלינן ביה כולי האי:"],[10,"מעשר שני","אע\"פ שהוא נאכל לישראל הואיל וקדש איקרי לא אמרי' ישרף אלא יגנזו וכן כתבי הקדש יגנזו:"],[11,"","ה\"ג כליל לה' אלהיך אר\"ש אמר הקב\"ה וכו' כאילו אתה מעלה עולה שהוא כליל לפני:"],[12,"לא תעשה גנות ופרדסין וכו'","בגמ' מפרש במאי פליגי:"],[12,"לכמו שהיתה","ביישוב בתים:"],[13,"גמ' יצאו הם ולא שלוחם","אם המדיחין עצמן יצאו והדיחן והרי הם מרובים ודנין בסייף אבל אם הדיחו ע\"י שליח כיחידים הם בסקילה וממונם פלט:"],[13,"אין אנשים פחות מב'","דע\"י מדיח אחד אין נעשית עיר הנדחת:"],[14,"בקרבך","משמע באמצע ולא מן הספר שאם היתה עיר של ספר בין מחוז עובדי כוכבים למחוז ישראל אינה נעשית עיר הנדחת דגזירת הכתוב היא שלא תעשה עיר הנדחת:"],[14,"יושבי העיר ולא יושבי עיר אחרת","דהיינו מדיחי' מחוצה לה:"],[14,"לאמר נלכה ונעבדה","משמע שצ\"ל לפנינו שכך אומרים נלכה ונעבדה ואין אמירה אלא בעדים אלמא צריך עדים לכל אחד ואחד שיעידו עליהם מה שאמרו וה\"נ צריך התראה לכל א' וא' מהם:"],[15,"חולקין עיר אחת","בתחלה כשחלקו ישראל את הארץ היו רשאין ליתן ולחלוק עיר א' לב' שבטים כגון אם אירע להם עיר בתחום ומקצת מושכת לתחום אחר שבט אחד נוטל חלק באותו קצת הארץ ע\"פ הגורל נחלקה הארץ אם נפתלי עולה תחום גינוסר עולה עמו דהכי אמרינן בב\"ב בפרק י\"נ ומנחילין (דף קכב.):"],[15,"אין חולקין","אלא כולה של אותו השבט שרוב' בתחומי':"],[15,"מאי לאו אע\"ג דמדיחיה מאותה עיר","אם יהיו מאותו שבט נעשית עיר הנדחת ואי לא לא שאם אינו מאותו שבט שהודחו אלא משבט אחר שבעיר אינו בסייף אלא בסקילה אלמא אפשר שיהו מן אותה העיר ולא מאותו שבט וה\"ד כגון שחלקו עיר אחת לשני שבטים:"],[16,"לא","לעולם אימא לך דאין חולקין והיכי משכחת לה מאותה עיר ולא מאותו שבט כגון דנפלה למדיחיה בירושה מקצת העיר ע\"י בת יורשת נחלה:"],[17,"ערים תשע מאת שני השבטים האלה","ממטה יהודה וממטה שמעון נטלו ט' ערים ונתנום ללוים:"],[17,"מאי לאו דשקל מהאי ד' ופלגא","שהיתה עיר א' של יהודה ושמעון ונטלו מהם אלמא חולקין עיר אחת לשני שבטים:"],[17,"","ה\"ג לא ד' מהאי וה' מהאי:"],[18,"א\"ה לפרוש פרושי","הי נינהו שבט דשקיל מיניה ה' והי נינהו דשקיל מיניה ד' ואמאי כתיב ערים תשע מאת שני השבטים משמע דבשוה שקל:"]],[]],[["קשיא","איבעיא להו הודחו מאליהן מהו וידיחו אמר רחמנא ולא שהודחו מאליהן או דילמא אפילו הודחו מאליהן","ת\"ש הדיחוה נשים וקטנים אמאי ליהוי כהודחו מאליהן הנך בתר נפשייהו גרידי הני בתר נשים וקטנים גרידי:","עד שיודח רובה: היכי עבדינן אמר רב יהודה דנין וחובשין דנין וחובשין א\"ל עולא נמצא אתה מענה את דינן של אלו אלא אמר עולא דנין וסוקלין דנין וסוקלין","איתמר רבי יוחנן אמר דנין וסוקלין דנין וסוקלין ור\"ל אמר מרבין להן בתי דינין","איני והאמר ר' חמא בר יוסי א\"ר אושעיא (דברים יז, ה) והוצאת את האיש ההוא או את האשה ההיא איש ואשה אתה מוציא לשעריך ואי אתה מוציא כל העיר כולה לשעריך אלא מרבין להן בתי דינין ומעיינין בדיניהן ומסקינן להו לבית דין הגדול וגמרי להו לדינייהו וקטלי להו:","הכה תכה את יושבי העיר וכו': תנו רבנן החמרת והגמלת העוברת ממקום למקום לנו בתוכה והודחו עמה אם נשתהו שם ל' יום הן בסייף וממונן אבד פחות מיכן הן בסקילה וממונן פלט","ורמינהי כמה יהיה בעיר ויהיה כאנשי העיר י\"ב חדש אמר רבא לא קשיא הא למיהוי מבני מתא הא למיהוי מיתבי מתא","והתניא המודר הנאה מבני העיר אם יש אדם שנשתהא שם י\"ב חדש אסור ליהנות ממנו פחות מיכן מותר ליהנות ממנו ביושבי העיר אם נשתהא ל' יום אסור ליהנות ממנו פחות מיכן מותר ליהנות ממנו:","החרם אותה ואת כל אשר בה כו': ת\"ר (דברים יג, טז) החרם אותה ואת כל אשר בה פרט לנכסי צדיקים שבחוצה לה ואת כל אשר בה לרבות נכסי צדיקים שבתוכה שללה ולא שלל שמים ואת כל שללה לרבות נכסי רשעים שחוצה לה","אמר ר\"ש מפני מה אמרה תורה נכסי צדיקים שבתוכה יאבדו מי גרם להם שידורו בתוכה ממונם לפיכך ממונם אבד אמר מר (דברים יג, יז) ואת כל שללה תקבץ לרבות נכסי רשעים שבחוצה לה אמר רב חסדא ובנקבצים לתוכה","אמר רב חסדא פקדונות של אנשי עיר הנדחת מותרין ה\"ד אי לימא דעיר אחרת ואיתנהו בגוה פשיטא דמותרין לאו שללה הוא ואלא דידהו ואיתנהו בעיר אחרת אי דנקבצין לתוכה אמאי מותרין ואי אין נקבצין לתוכה הא אמרה חדא זימנא","לא לעולם דעיר אחרת דמפקדי בתוכה והכא במאי עסקינן כגון דקביל עליה אחריות מהו דתימא כיון דקביל עליה אחריות כדידיה דמי קא משמע לן","אמר רב חסדא בהמה חציה של עיר הנדחת וחציה של עיר אחרת אסורה עיסה חציה של עיר הנדחת וחציה של עיר אחרת מותרת מאי טעמא בהמה כמאן דלא פליגא דמיא עיסה כמאן דפליגא דמיא","בעי רב חסדא בהמת עיר הנדחת מהו דתיתהני בה שחיטה לטהרה מידי נבילה לפי חרב אמר רחמנא לא שנא שחטה משחט לא שנא קטלא מקטל או דלמא כיון דשחטה מהניא לה שחיטה מאי תיקו","בעי רב יוסף שיער נשים צדקניות מהו אמר רבא הא דרשעיות אסור (דברים יג, יז) תקבץ ושרפת כתיב מי שאינו מחוסר אלא קביצה ושריפה יצא זה שמחוסר תלישה וקביצה ושריפה","אלא אמר רבא בפיאה נכרית היכי דמי אי דמחובר בגופה כגופה דמיא לא צריכא דתלי בסיבטא כנכסי צדיקים שבתוכה דמי ואבד או דלמא כיון דעיילא ונפקא כלבושה דמי תיקו:","ואת כל שללה תקבוץ אל תוך רחובה וכו': ת\"ר אין לה רחוב אינה נעשית עיר הנדחת דברי רבי ישמעאל רבי עקיבא אומר אין לה רחוב עושין לה רחוב במאי קמיפלגי מר סבר רחובה מעיקרא משמע ומר סבר רחובה השתא נמי משמע:"],[[0,"קשיא","לשון הפסוק קשה לתרץ למ\"ד חולקין אבל לא מיתותב:"],[2,"גרידי","בדל\"ת נמשכין וכן גריס רבי בכוליה הש\"ס מגריד גריד ונ\"ל שהוא לשון גרידא דמפרשינן יחיד על שם שהוא יחיד משוך ומופרש הוא מן הכל ואין לאחרים סביביו ולשון ארמי הוא ואין דומה לו בפסוק (ודומה לו) אבל גורדו ומעמידו על גלדו (ר\"ה ד' כז:) הוא לשון עברי ודומה לו בפסוק (איוב ב) ויקח לו חרס להתגרד בו בדל\"ת ופי' לשון חטיטה שמחטט וגורד בסכין או בכל דבר וגורר ברי\"ש לשון עברי הוא כמו (שבת ד' כב.) גורר אדם מטה כסא ושלחן וכן (ב\"ב ד' פו.) היה מגרר ויוצא מגרר ויוצא:"],[2,"בתר נפשייהו גרידי","ומעשיהם מעשה ואדוקים ביותר הואיל ומעצמם הם נדחין ודין הוא שיעשה עיר הנדחת:"],[2,"אבל הנך דהודחו בתר נשים וקטני גרידי","שאין אדוקים כ\"כ:"],[3,"היכי עבדינן","היאך נעשין רובא נדחים הואיל דצריכין עדים והתראה לכל אחד ואחד:"],[3,"דנין וחובשין","כשרואין ב' או ג' מהם עובדים ע\"ז לא יסקלו אותן ומניחין כל האחרים מלסקול אלא דנין אותם לסקילה וחובשין אותם בבית הסוהר וכן עושין עד שרואין אם מצטרפין לרובא וחוזרין ודנין אותם דין אחר להריגה ומאבדין את ממונם:"],[3,"ומענה את דינם","שלאחר שנגמר דינם אתה משהה אותם ומענה את דינם:"],[3,"דנין וסוקלין","עד חציין דמחזקינן להו כיחידים ודנין וסוקלין ומחציין ואילך נתברר הדבר למפרע שהודחו רובא והוו בסייף וממונם אבד ומחציין ואילך אי אתה רשאי למשכן למיתה חמורה:"],[4,"ור\"ל אמר מרבין להם בתי דינין","לאו משום דאין דנין ב' ביום אחד דהא אמרת בפרק נגמר הדין (לעיל סנהדרין מו.) דבמיתה אחת דנין אלא משום דנפישי עדים לכל אחד ואחד ואין פנאי לחקור כל אחד ואחד ביום אחד מרבים להם בתי דינים כדי שתתקבל עדותן ביום א' ויגמור דין כולם ביום אחד:"],[5,"לשעריך","לב\"ד שבשעריך דהיינו סנהדרי קטנה:"],[5,"ואי אתה מוציא","אלא בסנהדרי גדולה:"],[5,"אלא מרבין להם בתי דינין ומעייני בדיניהם","אם הוו מרובים ואם הודחו רוב' מעלים את כולן לב\"ד הגדול:"],[7,"כמה יהא בעיר","משנה בהשותפין:"],[7,"ויהא כאנשי העיר","ליתן בצורכי העיר:"],[7,"למיהוי כבני מתא","שיהא נקרא כבני העיר אין נקרא בפחות מי\"ב חדש אבל להקרות מיושבי העיר כיון ששהה ל' יום נקרא מאנשי העיר וקרינן בהו את יושבי העיר ההוא:"],[8,"והתניא","בניחותא:"],[8,"המודר הנאה","שאומר הרי עלי קונם אם אהנה:"],[9,"החרם אותה פרט לנכסי צדיקים שבחוצה לה","שאם היו צדיקים דרים בתוכה והוי להו נכסים מופקדים במקום אחר ביד אחרים אין מחרימין אותן אבל נכסים שיש להם באותה העיר מחרימין אותן וטעמא מפורש לקמן:"],[10,"אמר ר\"ש מפני מה וכו'","בכל דוכתי דרש ר\"ש טעמא דקרא:"],[10,"","ה\"ג אמר מר ואת כל (שללה) אשר בה לרבות נכסי רשעים שבחוצה לה:"],[10,"אמר רב חסדא ובנקבצין לתוכה","נכסי רשעים הקרובין לעיר שיכולים לקבצם לתוך העיר באותו יום עצמו שכונסין שלל העיר לרחוב לשורפן הן אבודים עמה אבל רחוקים דאין מגיעין לעיר אינן אבודים ודוקא שכבר היו לתוכה אלא שמעכשיו היו מופקדים ביד אחרים אבל לא היו מעולם בתוכה כגון דנפלה להם בירושה לא קרינא ביה שללה ואין הממון אבד:"],[11,"אלא דידהו","דבני עיר הנדחת ומופקדים הם בעיר אחרת:"],[11,"הא אמרה","רב חסדא ובנקבצין לתוכה והא אין נקבצין:"],[12,"דקבל עליו אחריות","בני עיר הנדחת:"],[13,"כמאן דלא פליגא","א\"א לכזית בשר בלא שחיטה ואפילו שחטה משחט אין בשחיטתו כלום דלא לשחיטה קיימא אלא למיתה ושחיטתה זו היא מיתת הבהמה ואין היתר אפילו החצי שאין של עיר הנדחת דכי שחט לסימן דעיר הנדחת אינו שוחט אלא ממית ולא מהניא ביה שחיטה:"],[13,"עיסה","כל אימת דבעי פליג לה ואין חלק של עיר הנדחת מעורב בו:"],[14,"ל\"ש שחטה משחט ל\"ש קטלא מקטיל","דבין בשחיטה ובין בהריגה קרינא ביה לפי חרב דאפילו שחטה מיתה בעלמא היא ולא מהני מידי או דילמא לפי חרב היינו שלא כדרך שחיטה אבל דרך שחיטה מהניא לה לטהרה מידי נבילה דנהי דלאכילה איתסרה ואיסור הנאה הוא אבל תיהני לטהרה מידי נבלה:"],[15,"שיער נשים צדקניות","שבעיר הנדחת מהו אי הוו בכלל ואת כל שללה תשרף או לא:"],[15,"רשעניות","פשיטא לן דישרף עם שלל העיר:"],[15,"תלישה","שצריך לגלחה:"],[16,"פיאה נכרית","גדיל של שערות דעלמא שעושין לנוי קא מבעי ליה לרב יוסף אם של צדקניות הוי:"],[16,"מחובר בגופה","שנקשר בה:"],[16,"כגופה דמי","וכשם שאין שורפין מלבושין שעליהן שהרי צדקניות הן כך אין שורפין אותו גדיל:"],[16,"דתלי בסבטא","תלה אותו גדיל ביתד ואין קשורין בה עכשיו:"],[16,"כיון דעיילא ונפקא","רגילה לקושרה תדיר אף על פי שלא קשרתו עכשיו כל מקום שיהא שם נדון כמלבוש שעליה דכל שעתא דעתה עליה וכשאר מלבושין דמי:"],[17,"רחובה מעיקרא משמע","רחובה שהיה לה מתחלה ולא שעושין לה רחוב עכשיו:"]],[]],[["וההקדשות שבה יפדו כו': ת\"ר היו בה (קדשי) קדשים קדשי מזבח ימותו קדשי בדק הבית יפדו ותרומות ירקבו ומעשר שני וכתבי הקדש יגנזו ר\"ש אומר בהמתה ולא בהמת בכור ומעשר שללה פרט לכסף הקדש וכסף מעשר","אמר מר היו בה (קדשי) קדשים קדשי מזבח ימותו ואמאי ימותו ירעו עד שיסתאבו וימכרו ויפלו דמיהן לנדבה","ר' יוחנן אמר (משלי כא, כז) זבח רשעים תועבה ר\"ל אמר ממון בעלים הוא והכא בקדשים שחייב באחריותן ור\"ש היא דאמר ממון בעלים הוא","הא מדסיפא ר\"ש היא רישא לאו ר\"ש בקדשים קלים ואליבא דרבי יוסי הגלילי דאמר קדשים קלים ממון בעלים אבל קדשי קדשים מאי יפדו","אדתני סיפא קדשי בדק הבית יפדו ליפלוג וליתני בדידה בד\"א בקדשים קלים אבל קדשי קדשים יפדו כיון דאיכא חטאת שמתו בעליה דלמיתה אזלא לא פסיקא ליה","בשלמא ר' יוחנן לא אמר כר\"ל דכתיב זבח רשעים תועבה אלא ר\"ל מ\"ט לא אמר כר' יוחנן אמר לך כי אמרינן זבח רשעים תועבה הני מילי היכא דאתנהו בעינייהו אבל הכא כיון דאישתני אישתני:","ר\"ש אומר בהמתך ולא בהמת בכור ומעשר: במאי עסקינן אילימא בתמימין שלל שמים הוא אלא בבעלי מומין שללה נינהו","אמר רבינא לעולם בבעלי מומין ומי שנאכל בתורת בהמתך יצאו אלו שאין נאכלין בתורת בהמתך אלא בתורת בכור ומעשר דשלל שמים נינהו","ופליגא דשמואל דאמר שמואל הכל קרב והכל נפדה מאי קאמר ה\"ק כל שקרב כשהוא תם ונפדה כשהוא בעל מום משלל אימעיט וכל שקרב כשהוא תם ואינו נפדה כשהוא בעל מום כגון בכור ומעשר מבהמה נפקא:","תרומות ירקבו: אמר רב חסדא ל\"ש אלא תרומה ביד ישראל אבל תרומה ביד כהן כיון דממוניה הוא תשרף","מתיב רב יוסף מעשר שני וכתבי הקדש יגנזו והא מעשר שני ביד ישראל כתרומה ביד כהן דמי וקתני יגנזו אלא אי אתמר הכי אתמר אמר רב חסדא ל\"ש אלא תרומה ביד כהן אבל תרומה ביד ישראל תנתן לכהן שבעיר אחרת","תנן התם עיסה של מעשר שני פטורה מן החלה דברי ר\"מ וחכמים מחייבין אמר רב חסדא מחלוקת במעשר שני בירושלים דר\"מ סבר מעשר שני ממון גבוה הוא ורבנן סברי ממון הדיוט הוא אבל בגבולין דברי הכל פטור","מתיב רב יוסף מעשר שני וכתבי הקדש יגנזו במאי עסקינן אילימא בירושלים מי הויא עיר הנדחת והתניא עשרה דברים נאמרו בירושלים וזו אחת מהן אינה נעשית עיר הנדחת ואלא בעיר אחרת ואסקוהו לגוה הא קלטוהו מחיצות","אלא לאו בגבולין וקתני יגנזו לא לעולם דעיר אחרת ואסקוהו לגוה והכא במאי עסקינן שנטמא","ולפרקיה דא\"ר אלעזר מניין למעשר שני שנטמא שפודין אותו אפילו בירושלים ת\"ל (דברים יד, כד) לא תוכל שאתו ואין שאת אלא אכילה שנאמר (בראשית מג, לד) וישא משאת מאת פניו הכא במאי עסקינן בלקוח"],[[0,"היו בה קדשי מזבח","כגון עולות ואשמות של רשעים בתוכה נהי דלא קרינן בהו את כל בהמתה לפי חרב דהא לא בהמתה היא אלא בהמת שמים אלא מאיסותא הוא להקריב קרבנות של רשעים הללו שהודחו הלכך ימותו כונסין אותן לכיפה ומאכילין אותן שעורין עד שכריסן נבקעת דאפילו דמיהם אסור כדלקמן:"],[0,"","שנאמר כליל לה' אלהיך ל\"ג:"],[0,"ר\"ש אומר וכו'","לקמן מפרש טעמא:"],[2,"זבח רשעים תועבה","ואפילו דמיהן אסורין:"],[2,"ור\"ש הוא דאמר","בהזהב (ב\"מ נו:) קדשים שחייב באחריותן ממון בעלים הוא ויש בהם אונאה הלכך לענין עיר הנדחת נמי ממון . בעלים הוא ודיינינהו לפי חרב כשאר בהמות שבתוכה והלכך אסורין דמיהן בהנאה והאי דקאמר ימותו ולא אמר שיחרימו אותה עמהם משום כבוד שמים:"],[3,"ואליבא דרבי יוסי הגלילי דאמר","בפ\"ק דב\"ק (ד' יב:) ומעלה מעל בה' לרבות קדשים קלים שהם ממונו והואיל וממונו הם אסורים בהנאה דאפילו דמיהן בהמתם מיקרו אבל קדשי קדשים אמאי ירעו דהא ודאי הם עצמם אינם קרבים דזבח רשעים תועבה אלא ירעו עד שיסתאבו וימכרו ויפלו דמיהם לנדבה:"],[4,"אי הכי מדתני סיפא וכו'","דקא מפליג בין קדשי מזבח לקדשי בדק הבית:"],[4,"ליפלוג וליתני בדידה","בקדשי מזבח עצמן בין קדשים קלים לקדשי קדשים:"],[4,"דלמיתה אזלא","כדאמרינן (תמורה ד' טז.) חמש חטאות מתות:"],[4,"לא פסיקא ליה","למיתני קדשי קדשים דעיר הנדחת ירעו דכיון דמתו להם אותם רשעים אי איכא חטאות שהפרישו בחייהם אזלי למיתה דכל חטאות שמתו בעליהם מתות במסכת הוריות (ד' ו.) מפרש טעמא אבל שאר קדשי קדשים כגון אשמות שמתו בעליהם ירעו:"],[5,"דאיתנהו בעינייהו","דהן עצמן ודאי אינן קרבים משום זבח רשעים תועבה:"],[5,"אבל הכא","דאיכא למימר ירעו ויפלו דמיהם לנדבה:"],[5,"כיון דאישתני","ליכא הכא זבח רשעים תועבה:"],[6,"ולא בהמת בכור ומעשר","שאם היו בה בכורות או מעשר בהמה שהוא של ישראל וחלבו ודמו קרב אין מחרימין אותו עמה דלא מיקרי בהמתה:"],[6,"שלל שמים הוא","ומשללה נפקא:"],[6,"אלא בבעלי מומים","שאין בהם חלק לגבוה אלא נאכלין לבעלים שללה נינהו אמאי אין מחרימין אותן עמה:"],[7,"לעולם בבעלי מומין","ואפ\"ה אין נשרפין עמה דדרשינן לקרא הכי בהמתה למי שנאכל לבעלים בתורת בהמתם יצאו אלו שיש להם שם לווי שאין נאכלים בתורת בהמתם שאין אומרין בהמת עיר הנדחת אלא בהמת בכור ומעשר של עיר הנדחת:"],[8,"ופליגא","הא דרבינא אדשמואל דאמר שמואל עלה דהא מילתא דר\"ש כי הוה קשיא לן במאי עסקינן הוי מתרץ הכי הכל קרב והכל נפדה:"],[8,"מאי קאמר ה\"ק כל","שהוא קרב לגבוה כשהוא תם וכשהוא בעל מום צריך פדייה כגון שאר קדשים קלים חוץ ממעשר בהמה ובכור הנהו משללה נפקא דאין מחרימין אותם עמה דהואיל וצריכי פדייה במומן שלל שמים קרינן ביה ופליג עליה דת\"ק דאמר קדשים קלים ממון בעלים הוא:"],[8,"וכל שקרב כשהוא תם ואינו נפדה כשהוא בעל מום","אלא נאכל לבעלים כגון בכור ומעשר ההוא לאו שלל שמים מקרו ואפילו בתמותן ולא מצי למפרך והא בתמותן שלל שמים הוא שהרי נאכל במומו והלכך אצטריך בהמתה למעוטי בכור ומעשר תמימים דמשללה ליכא למעוטינהו והיינו פליגא דאיהו מוקי לה אפילו בתמימים דקסבר בכור ומעשר בעלי מומין בהמתה קרינא ביה ובסייף:"],[9,"תרומה ביד ישראל","שעדיין לא נתנה לכהן דאפילו אותו ישראל רשע הוא תרומה שבידו אינה נשרפת עם שאר שללה דהא לאו דידיה הוא דשמא היה נתנה לכהן צדיק שבחוצה לה הלכך אינה נשרפת דהיינו כפקדון דעיר אחרת ואתנהו בגוה דאמר לעיל דמותרין ונהי דבאכילה לא שרינא לה דשמא היה נתנה לכהן רשע שבתוכה הלכך ירקבו אבל תרומה ביד כהן דממוניה הוא תשרף:"],[10,"וקתני יגנזו","אע\"ג דממוניה הוא לא אמר תשרף:"],[10,"אלא תרומה ביד כהן","דממוניה הוא ולא מזלזלינן בה כולי האי הואיל וקדש הוא:"],[10,"לכהן שבעיר אחרת","כלומר לכהן שלא הודח עמהן:"],[11,"אבל בגבולין","שאין לה היתר אכילה אלא בפדייה ד\"ה פטורה מן החלה דממון גבוה הוא ל\"א אבל בגבולין דאין לה היתר אכילה בשעת חיוב חלה דהיינו בשעת גלגול העיסה לא קרינא ביה ראשית עריסותיכם (במדבר ט״ו:כ׳) ואפילו פדאה לאחר מיכן פטור מן החלה:"],[12,"י' דברים נאמרו בירושלים","בפ' מרובה (ב\"ק פב:) חשיב להו:"],[12,"אלא בעיר אחרת ואסקו לגוה","שהיה אותו מעשר שני של אחד מבני עיר הנדחת והעלו אותו לירושלים קודם שהודחה ואח\"כ הודחו אם כן אמאי יגנזו לשתרו נמי באכילה דהא קלטינהו מחיצות דהיינו חומה:"],[13,"אלא לאו בגבולין","ולא מטו ליה וקתני יגנזו ואינו יוצא לישרף בתמיה:"],[13,"ואם איתא","דבגבולין לד\"ה ממון גבוה הוא לשתרי נמי באכילה אלא לאו ממון הדיוט הוא ונהי דבשריפה לא משום זילותא:"],[13,"לעולם דעיר הנדחת ואסקיה לגוה","ודקאמרת לשתרו נמי באכילה דהא קלטוהו מחיצות:"],[13,"הכא במאי עסקינן כשנטמא","דלאו בר אכולי בטומאה הוא דכתיב (דברים כ״ו:י״ד) לא בערתי ממנו בטמא ולקמן פריך מאי איריא עיר הנדחת אפילו בחוצה לה:"],[14,"ואפילו בירושלים","לאחר שנכנס ואע\"ג דדרשינן (שם יד) כי ירחק ממך המקום וצרת הכסף בידך ברחוק מקום אתה פודה וצר ולא בקרוב מקום:"],[14,"ואין שאת אלא אכילה","וה\"ק קרא כי ירחק ממך המקום או כי לא תוכל לאוכלו שנטמא וצרת הכסף בידך:"],[14,"בלקוח","שכבר הוציאה בהוצאה לכסף מעשר ונתנוהו ביין ושכר ובשר ונטמא אותו לקוח דההוא לית ליה פדייה וכי קאמר ר\"א במע\"ש גופיה שהעלה פירות מע\"ש לירושלים ונטמאו:"]],[]],[["וליפרקיה דתנן הלקוח בכסף מעשר שנטמא יפדה כר\"י דאמר יקבר אי הכי מאי איריא עיר הנדחת אפילו דעלמא נמי","אלא לעולם בטהור וכגון דנפול מחיצות וכדרבא דאמר רבא מחיצה לאכול דאורייתא לקלוט דרבנן וכי גזור רבנן כי אתנהו למחיצה כי ליתנהו למחיצה לא:","כתבי הקדש יגנזו: מתניתין דלא כר\"א דתניא ר\"א אומר כל עיר שיש בה אפי' מזוזה אחת אינה נעשית עיר הנדחת שנא' (דברים יג, יז) ושרפת באש את העיר ואת כל שללה כליל והיכא דאיכא מזוזה לא אפשר דכתיב (דברים יב, ד) לא תעשון כן לה' אלהיכם:","ר\"ש אומר אמר הקב\"ה וכו': לימא בדר' אבין א\"ר אילעא קמיפלגי דא\"ר אבין א\"ר אילעא כל מקום שאתה מוצא כלל בעשה ופרט בלא תעשה אין דנין אותו בכלל ופרט","דמר אית ליה דרבי אבין ומר לית ליה דרבי אבין","לא דכ\"ע אית להו דר' אבין והכא בהא קמיפלגי מר סבר עוד לגמרי משמע ומר סבר עוד לכמה שהיתה אינה נבנית אבל נעשית היא גנות ופרדסים:","ת\"ר היו בה אילנות תלושין אסורין מחוברין מותרין של עיר אחרת בין תלושין בין מחוברין אסור מאי עיר אחרת אמר רב חסדא יריחו דכתיב (יהושע ו, יז) והיתה העיר חרם לה' וישבע יהושע בעת ההיא לאמר ארור האיש לפני ה' אשר יקום ובנה את העיר הזאת את יריחו בבכורו ייסדנה ובצעירו יציב דלתיה","תניא לא יריחו על שם עיר אחרת ולא עיר אחרת על שם יריחו דכתיב (מלכים א טז, לד) בנה חיאל בית האלי את יריחו באבירם בכורו יסדה ובשגוב צעירו הציב דלתיה","תניא באבירם בכורו רשע לא היה לו ללמוד בשגוב צעירו היה לו ללמוד","אבירם ושגוב מאי עבוד (מאי קאמר) ה\"ק באבירם בכורו היה לו ללמוד לאותו רשע בשגוב צעירו ממשמע שנאמר באבירם בכורו איני יודע ששגוב צעירו מה ת\"ל שגוב צעירו מלמד שהיה מקבר והולך מאבירם עד שגוב","אחאב שושביניה הוה אתא איהו ואליהו למשאל בשלמא בי טמיא יתיב וקאמר דילמא כי מילט יהושע הכי לט לא יריחו על שם עיר אחרת ולא עיר אחרת על שם יריחו א\"ל אליהו אין אמר ליה השתא לווטתא דמשה לא קא מקיימא דכתיב (דברים יא, טז) וסרתם ועבדתם וגו' וכתיב וחרה אף ה' בכם ועצר את השמים וגו' וההוא גברא אוקים ליה עבודת כוכבים על כל תלם ותלם ולא שביק ליה מיטרא דמיזל מיסגד ליה לווטתא דיהושע תלמידיה מקיימא","מיד (מלכים א יז, יג) ויאמר אליהו התשבי מתושבי גלעד חי ה' אלהי ישראל אם יהיה טל ומטר וגו' בעי רחמי והבו ליה אקלידא דמטרא וקם ואזל","(מלכים א יז, ב) ויהי דבר ה' אליו לאמר לך מזה ופנית לך קדמה ונסתרת בנחל כרית (מלכים א יז, ו) והעורבים מביאים לו לחם ובשר בבקר וגו' מהיכא אמר רב יהודה אמר רב מבי טבחי דאחאב (מלכים א יז, ז) ויהי מקץ ימים וייבש הנחל כי לא היה גשם בארץ כיון דחזא דאיכא צערא בעלמא כתיב (מלכים א יז, ב) ויהי דבר ה' אליו לאמר קום לך צרפתה","וכתיב (מלכים א יז, יז) ויהי אחר הדברים האלה חלה בן האשה בעלת הבית בעא רחמי למיתן ליה אקלידא דתחיית המתים אמרי ליה שלש מפתחות לא נמסרו לשליח של חיה ושל גשמים ושל תחיית המתים יאמרו שתים ביד תלמיד ואחת ביד הרב אייתי הא ושקיל האי דכתיב (מלכים א יח, א) לך הראה אל אחאב [ואתנה] מטר","דרש ההוא גלילאה קמיה דרב חסדא משל דאליהו למה הדבר דומה לגברא דטרקיה לגליה ואבדיה למפתחיה","דרש ר' יוסי בצפורי אבא אליהו"],[[0,"וליפרקיה לכוליה","ומשני כר\"י דאמר לא אלים למתפס פדיונו בההיא מנה גופא במס' מעשר שני (פ\"ג מ\"י) והיינו נמי מעשר שני דקאמר יגנז בקבורה:"],[1,"אלא לעולם","במעשר שני דעיר הנדחת טהור ואסקוה לגוה ודקאמר לישתרי באכילה דהא קלטוהו מחיצות אחר שנכנס לחומת ירושלים: דאמר רבא בשחיטת חולין פ' בהמה המקשה (חולין דף סח):"],[1,"מחיצות לאכול דאורייתא","מן התורה מצוה לאכול לפנים מן החומה:"],[1,"אבל מחיצות לקלוט","שיהיו מחיצות קולטות בין לענין פדייה בין לכל ענין מדרבנן הוא וכי גזור רבנן דתיהני קליטת מחיצות למעשר דשוב אינו יכול לפדותו ולענין עיר הנדחת נמי שלא יהא בשריפה היכא דאיתנהו מחיצות:"],[2,"דכתיב ואבדתם","את שמם מן המקום ההוא וגו' וסמיך ליה לא תעשון כן לה' אלהיכם ובמזוזה הואיל וכתיב בה אזכרות אי אפשר לשריפה משום קרא דלא תעשון כן ואנן בעינן שללה וליכא דהאי שלל שמים הוא:"],[3,"כלל בעשה ופרט בלא תעשה","כגון והיתה תל עולם כלל דאפילו גנות ופרדסים לא תעשה אלא תהיה תל עולם שהוא עשה לא תבנה עוד בנין בתים והוא לא תעשה אין דנין אותו בכלל ופרט לומר אין בכלל אלא מה שבפרט דלא תעשה פירוש הוא כלומר והיתה תל עולם לבנין קאמר אבל לגנות ופרדסים שרי אלא תרי מילי קאמר קרא דלא אמרינן פירושי קמפרש אלא מילי מילי קאמר והיתה תל עולם לגנות ופרדסים לא תבנה עוד כל בנינין שבעולם ואפילו לגנות ופרדסים לא תבנה עוד ודרשינן ליה לדבר שהיה בכלל ויצא מן הכלל ללמד לא ללמד על עצמו יצא אלא ללמד על הכלל כולו יצא ולומר בנין בכלל היה ולמה יצא להקיש לך מה בנין מיוחד שהוא ישוב בני אדם אף כל בנין כגון גנות ופרדסים (לישנא אחרינא) ור' יוסי הגלילי סבר אין דנין כר' אבין ודריש הכי והיתה תל עולם מכל מילי שלא יעשה בה שום דבר ולא תבנה עוד דמשמע בנין בתים אשמועינן לאו בבנין בתים וגנות ופרדסים איסור עשה הוא דאיכא. כך שמעתי:"],[4,"ר\"ע סבר דנין","דלא כר' אבין:"],[5,"דכ\"ע אית להו דר' אבין","ואפילו ר\"ע והא דקאמר דעיר הנדחת נעשית גנות ופרדסים לאו משום דבעלמא לית ליה דר' אבין דודאי מלתא קא מפרשי והיתה תל עולם במאי בבנין בתים דלא תבנה עוד לא משמע ליה בכל בנינין דקסבר עוד לכמו שהיתה משמע כלומר לא תחזור ולא תבנה עוד משמע כגון שהיתה מתחלה לא תבנה עוד אבל נעשה גנות ופרדסים:"],[5,"ומר סבר עוד לגמרי משמע","כגון דאמר לעולם ועד ועוד לשון ועד הוא שלא תבנה לעולם לשום דבר לא לבנין בתים ולא לגנות ופרדסים לא תבנה עוד:"],[6,"מחוברין מותרין","דתקבוץ ושרפת אמרה רחמנא מי שאינו מחוסר אלא קביצה ושריפה יצא זה שמחוסר תלישה וקביצה ושריפה:"],[6,"וכל אשר בה","אפילו אילנות מחוברין אשר בה נאסרין:"],[6,"ה\"ג וישבע יהושע לאמר ארור האיש וגו'","וקרא קדריש ואזיל בבכורו ייסדנה ובצעירו יציב דלתיה וכשיעמיד דלתיה ימות בנו הקטן:"],[7,"לא יריחו על שם עיר אחרת","שלא יבנה יריחו ויסב שמה על שם עיר אחרת ולא עיר אחרת על שם יריחו שאפי' בנה עיר אחרת וקראה יריחו אסור לבנותה שאפי' שם יריחו ימחה לעולם וכתיב בימיו בנה חיאל בית האלי את יריחו בימיו של אחאב ועל שעבר על האלה קרי ליה בית האלי:"],[7,"את יריחו","ולא יריחו עצמו בנה אלא עיר אחרת על שם יריחו שקראה לה יריחו ולא אתפרש הא מנלן:"],[7,"באבירם בכורו יסדה","אבירם רשע כשמת אבירם הרשע לא היה לו לחיאל ללמוד שלא לבנות את יריחו:"],[9,"אבירם ושגוב מאי עבוד","דקרי להו רשעים:"],[9,"איני יודע ששגוב צעירו","מילתא באנפי נפשיה הוא ולמדרשא ממשמע שנאמר באבירם בכורו איני יודע ששגוב צעירו אלא מה ת\"ל שגוב צעירו שהיה קובר והולך מאבירם ועד שגוב שהוא צעיר מכלם:"],[10,"אחאב שושבינו","אוהבו של חיאל היה אחאב:"],[10,"בי טמיא","וי\"א בי טעמא בית האבל שמטעימים אותו בדברים לנחמו ובכמה דוכתין כתיב בבראשית רבה טמיא בלא עיי\"ן לשון אבל:"],[10,"על כל תלם ותלם","שורה וערוגה ומקום גבוה הוא:"],[10,"ולא שביק מיטרא מיזל ומסגד","שהיה הלכלוך הולך וגדל מרוב הגשמים הבאין לעולם שאין מניחין לילך להשתחוות לעבודת כוכבים מתוך דרכים מלוכלכות בטיט:"],[11,"מיד ויאמר אליהו חי ה' אם יהיה השנים האלה מטר וגו'","האי קרא סמוך לקרא דחיאל בית האלי:"],[11,"אקלידא דמטרא","מפתח של מטר:"],[12,"כיון דחזא","הקב\"ה דאיכא צערא בעלמא א\"ל הקב\"ה לאליהו לך צרפתה לגלגל הדבר שיחזיר לו מפתח של מטר כדקא מפרש ואזיל:"],[13,"שלש מפתחות לא נמסרו ביד שליח","על אוצרו של הקב\"ה יש מפתחות ומסרם ליד שלוחים הממונים אבל ג' מפתחות יש לו בידו שלא מינה שליח עליהם מבראשית אלא בידו הם ולא רצה למסור שליח עליהם וקאמר הקב\"ה לאליהו אותם ג' מפתחות עכבתי בידי מבראשית ולא מניתי שליח עליהם אלא אותך שעשיתי ממונה על אחת מהם ועתה תשאל מפתח שני יאמרו שנים ביד תלמיד ואחד ביד הרב:"],[13,"דכתב לך הראה אל אחאב ואתנה מטר","ולא כתיב ותן מטר:"],[14,"דטרקיה לגליה","שסתם שער שלו ואבדיה למפתחיה כך עשה אליהו נעל לשערי מטר ולבסוף אבד המפתח של גשמים שלא נפתח השער של מטר על ידו:"],[15,"אבא אליהו","חביבי וגדולי:"]],[]],[["קפדן הוה רגיל למיתי גביה איכסי' מיניה תלתא יומי ולא אתא כי אתא א\"ל אמאי לא אתא מר א\"ל קפדן קרית לי א\"ל הא דקמן דקא קפיד מר:","(דברים יג, יח) ולא ידבק בידך מאומה מן החרם כל זמן שרשעים בעולם חרון אף בעולם וכו': מאן רשעים אמר רב יוסף גנבי","ת\"ר רשע בא לעולם חרון בא לעולם שנא' (משלי יח, ג) בבא רשע בא גם בוז ועם קלון חרפה רשע אבד מן העולם טובה באה לעולם שנא' (משלי יא, י) ובאבוד רשעים רנה צדיק נפטר מן העולם רעה באה לעולם שנאמר (ישעיהו נז, א) הצדיק אבד ואין איש שם על לב ואנשי חסד נאספים באין מבין כי מפני הרעה נאסף הצדיק צדיק בא לעולם טובה באה לעולם שנאמר (בראשית ה, כט) זה ינחמנו ממעשינו ומעצבון ידינו:","\u0001הדרן עלך כל ישראל יש להם חלק וסליקא לה מסכת סנהדרין\u0002"],[[0,"היה קפדן","שכעס על אחאב ואמר חי ה' אם יהיה השנים האלה טל ומטר:"],[0,"איכסי' מיניה","שהיה רגיל למיתי לבי מדרשו כל יומא ולא אתא בתלתא יומי:"],[0,"א\"ל","ר' יוסי:"],[0,"הא דקמא דקא קפיד מר","הרי על דבר זה שאמרתי עליך קפיד שלא באת אלי ג' ימים מקפדנות שקצפת עלי:"],[2,"מפני הרעה","קודם שתבא הרעה הצדיק נאסף מכלל דכיון שמת הרעה באה:"],[2,"","אבל צדיק בא לעולם פסקה הרעה שנאמר זה ינחמנו:"]],[]]]};
